if [[ -t 1 && -z "${NO_COLOR:-}" ]]; then
    RESET=$'\033[0m' BOLD=$'\033[1m' DIM=$'\033[2m' ITALIC=$'\033[3m'
    CLR_PRIMARY=$'\033[38;5;39m'   # Sky Blue / Electric Cyan
    CLR_ACCENT=$'\033[38;5;213m'   # Soft Magenta
    CLR_SUCCESS=$'\033[38;5;82m'   # Bright Emerald Green
    CLR_WARN=$'\033[38;5;214m'      # Warm Amber Yellow
    CLR_ERROR=$'\033[38;5;196m'     # Vivid Crimson Red
    CLR_MUTED=$'\033[38;5;244m'     # Medium Slate Gray
    CLR_TEXT=$'\033[38;5;255m'      # High-contrast White
    CLR_CARD=$'\033[48;5;236m'      # Dark background card
    SYM_OK="✓" SYM_FAIL="✗" SYM_WARN="!" SYM_INFO="i" SYM_Q="?" SYM_DOT="●" SYM_CIRCLE="○"
else
    RESET='' BOLD='' DIM='' ITALIC=''
    CLR_PRIMARY='' CLR_ACCENT='' CLR_SUCCESS='' CLR_WARN='' CLR_ERROR='' CLR_MUTED='' CLR_TEXT='' CLR_CARD=''
    SYM_OK="[OK]" SYM_FAIL="[ERR]" SYM_WARN="[!]" SYM_INFO="[i]" SYM_Q="[?]" SYM_DOT="*" SYM_CIRCLE="o"
fi

# Standardized indentation constants (2-space increments)
INDENT_1="  "
INDENT_2="    "
INDENT_3="      "

# ---------------------------------------------------------------------------
# UI Logging Primitives
# ---------------------------------------------------------------------------
log_info()    { local ind="${LOG_INDENT:-  }"; printf '%s%s %s\n' "$ind" "${CLR_MUTED}${SYM_INFO}${RESET}"   "$1" >&2; }
log_success() { local ind="${LOG_INDENT:-  }"; printf '%s%s %s\n' "$ind" "${CLR_SUCCESS}${SYM_OK}${RESET}"    "$1" >&2; }
log_warn()    { local ind="${LOG_INDENT:-  }"; printf '%s%s %s\n' "$ind" "${CLR_WARN}${SYM_WARN}${RESET}"     "$1" >&2; }
log_error()   { local ind="${LOG_INDENT:-  }"; printf '%s%s %s\n' "$ind" "${CLR_ERROR}${BOLD}${SYM_FAIL}${RESET}" "$1" >&2; }
log_action()  { local ind="${LOG_INDENT:-  }"; printf '%s%s\n' "$ind" "$1" >&2; }

_ui_header() {
    local title="$1"
    if [[ -t 1 && -z "${NO_COLOR:-}" ]]; then
        printf '\n%s\n\n' "${BOLD}${title}${RESET}" >&2
    else
        printf '\n%s\n\n' "$title" >&2
    fi
}

_ui_bell() {
    [[ "${NON_INTERACTIVE:-false}" == true || "${DOTFILES_NO_BELL:-false}" == true ]] && return 0
    local bell_file="${TMPDIR:-/tmp}/.dotfiles_bell_$$"
    local now
    now="$(date +%s 2>/dev/null || printf '%s' "${SECONDS:-0}")"
    local last=0
    if [[ -f "$bell_file" ]]; then
        last="$(<"$bell_file")" 2>/dev/null || last=0
    fi
    local min_interval=45
    if [[ $(( now - last )) -ge $min_interval ]]; then
        printf '%s' "$now" > "$bell_file" 2>/dev/null || true
        if [[ -t 2 || -c /dev/tty ]]; then
            printf '\a' >&2
        fi
    fi
}

_ui_input() {
    local prompt="$1" default_val="${2:-}"
    local ind="${LOG_INDENT:-  }"
    if [[ "${NON_INTERACTIVE:-false}" == true ]]; then
        printf '%s' "$default_val"
        return 0
    fi
    _ui_bell
    local val="" hint=""
    [[ -n "$default_val" ]] && hint=" ${CLR_MUTED}(${default_val})${RESET}"
    printf '%s%s %s%s: ' "$ind" "${CLR_PRIMARY}${SYM_Q}${RESET}" "${BOLD}${prompt}${RESET}" "$hint" >&2
    if [[ ! -t 0 ]]; then
        read -r val 2>/dev/null || true
    elif [[ -c /dev/tty ]]; then
        read -r val < /dev/tty 2>/dev/null || read -r val 2>/dev/null || true
    else
        read -r val 2>/dev/null || true
    fi
    local res="${val:-$default_val}"
    if [[ -t 2 && -c /dev/tty ]]; then
        local display_res
        if [[ -z "$res" ]]; then
            display_res="${CLR_MUTED}(skipped)${RESET}"
        else
            display_res="${CLR_TEXT}${res}${RESET}"
        fi
        printf '\033[1A\033[2K%s%-12s %s\n' "$ind" "${prompt}" "$display_res" >&2
    fi
    printf '%s' "$res"
}

_ui_password() {
    local prompt="$1"
    local ind="${LOG_INDENT:-  }"
    if [[ "${NON_INTERACTIVE:-false}" == true ]]; then
        printf ''
        return 0
    fi
    _ui_bell
    local val=""
    printf '%s%s %s: ' "$ind" "${CLR_WARN}${SYM_Q}${RESET}" "${BOLD}${prompt}${RESET}" >&2
    if [[ ! -t 0 ]]; then
        read -r -s val 2>/dev/null || true
    elif [[ -c /dev/tty ]]; then
        read -r -s val < /dev/tty 2>/dev/null || read -r -s val 2>/dev/null || true
    else
        read -r -s val 2>/dev/null || true
    fi
    printf '\n' >&2
    if [[ -t 2 && -c /dev/tty ]]; then
        printf '\033[1A\033[2K%s%-12s %s\n' "$ind" "${prompt}" "${CLR_MUTED}••••••••${RESET}" >&2
    fi
    printf '%s' "$val"
}

_ui_select() {
    local prompt="$1"
    shift
    local opts=("$@")
    if [[ "${NON_INTERACTIVE:-false}" == true || ${#opts[@]} -eq 0 ]]; then
        printf '%s' "${opts[0]:-}"
        return 0
    fi
    _ui_bell

    if [[ -t 0 && -t 2 && -c /dev/tty ]]; then
        local selected=0
        local total=${#opts[@]}
        local key=""
        printf '\033[?25l' >&2 # Hide cursor

        _render_menu() {
            printf '  %s %s\n' "${CLR_PRIMARY}${SYM_Q}${RESET}" "${BOLD}${prompt}${RESET}" >&2
            local i
            for i in "${!opts[@]}"; do
                if [[ $i -eq $selected ]]; then
                    printf '    %s %s\n' "${CLR_PRIMARY}●${RESET}" "${BOLD}${CLR_PRIMARY}${opts[$i]}${RESET}" >&2
                else
                    printf '    %s %s\n' "${CLR_MUTED}○${RESET}" "${CLR_MUTED}${opts[$i]}${RESET}" >&2
                fi
            done
        }

        _render_menu

        while true; do
            IFS= read -rsn1 key < /dev/tty 2>/dev/null || break
            if [[ "$key" == $'\x1b' ]]; then
                read -rsn2 -t 0.1 rest < /dev/tty 2>/dev/null || rest=""
                key+="$rest"
            fi

            case "$key" in
                $'\x1b[A'|k|K)
                    selected=$(( (selected - 1 + total) % total ))
                    ;;
                $'\x1b[B'|j|J)
                    selected=$(( (selected + 1) % total ))
                    ;;
                "")
                    break
                    ;;
                [1-9])
                    local num=$((key - 1))
                    if [[ $num -ge 0 && $num -lt $total ]]; then
                        selected=$num
                        break
                    fi
                    ;;
                q|Q)
                    break
                    ;;
            esac

            printf '\033[%dA' "$((total + 1))" >&2
            _render_menu
        done

        printf '\033[?25h' >&2 # Restore cursor
        printf '\033[%dA\033[J' "$((total + 1))" >&2
        printf '  %s %s: %s\n' "${CLR_SUCCESS}${SYM_OK}${RESET}" "${prompt}" "${CLR_PRIMARY}${BOLD}${opts[$selected]}${RESET}" >&2
        printf '%s' "${opts[$selected]}"
        return 0
    fi

    printf '  %s %s\n' "${CLR_PRIMARY}${BOLD}${prompt}${RESET}" >&2
    local i
    for i in "${!opts[@]}"; do
        printf '    %s%2d)%s %s\n' "${CLR_ACCENT}" $((i + 1)) "${RESET}" "${opts[$i]}" >&2
    done
    local choice=""
    printf '  Select [1-%d]: ' "${#opts[@]}" >&2
    if [[ ! -t 0 ]]; then
        read -r choice 2>/dev/null || true
    elif [[ -c /dev/tty ]]; then
        read -r choice < /dev/tty 2>/dev/null || read -r choice 2>/dev/null || true
    else
        read -r choice 2>/dev/null || true
    fi
    if [[ "$choice" =~ ^[0-9]+$ ]]; then
        local idx=$((choice - 1))
        if [[ "$idx" -ge 0 && "$idx" -lt "${#opts[@]}" ]]; then
            printf '%s' "${opts[$idx]}"
            return 0
        fi
    fi
    printf '%s' "${opts[0]}"
}

_ui_multiselect() {
    local prompt="$1"
    local -n _ms_items="$2"
    local -n _ms_labels="$3"
    local -n _ms_descs="$4"
    local -n _ms_states="$5"
    local -n _ms_locks="$6"

    local total=${#_ms_items[@]}
    if [[ $total -eq 0 ]]; then
        return 0
    fi

    if [[ "${NON_INTERACTIVE:-false}" == true || ! -t 0 || ! -t 2 || ! -c /dev/tty ]]; then
        local out_items=()
        local i
        for i in "${!_ms_items[@]}"; do
            local lock="${_ms_locks[$i]:-}"
            local st="${_ms_states[$i]:-0}"
            if [[ "$lock" == "required" || "$st" -eq 1 ]]; then
                [[ "$lock" != "unsupported:"* && "$lock" != "disabled"* ]] && out_items+=("${_ms_items[$i]}")
            fi
        done
        printf '%s ' "${out_items[@]}"
        return 0
    fi

    _ui_bell
    local selected=0
    local key=""
    printf '\033[?25l' >&2

    local max_name_len=0
    local max_tag_len=0
    local _idx
    for _idx in "${!_ms_items[@]}"; do
        local _item="${_ms_items[$_idx]}"
        local _lbl="${_ms_labels[$_idx]:-$_item}"
        local _lock="${_ms_locks[$_idx]:-}"
        [[ ${#_lbl} -gt $max_name_len ]] && max_name_len=${#_lbl}

        local _rtag=""
        if [[ "$_lock" == "required" ]]; then
            _rtag="required"
        elif [[ "$_lock" == "installed:"* || "$_lock" == "installed" ]]; then
            _rtag="already installed"
        elif [[ "$_lock" == "alt:"*" installed" ]]; then
            local _at="${_lock#alt:}"
            _at="${_at% installed}"
            _rtag="modern replacement for ${_at}"
        elif [[ "$_lock" == "alt:"* ]]; then
            local _at="${_lock#alt:}"
            _rtag="alternative to ${_at}"
        elif [[ "$_lock" == "unsupported:"* ]]; then
            local _r="${_lock#unsupported:}"
            _rtag="unavailable on ${_r}"
        elif [[ "$_lock" == "disabled:missing "* ]]; then
            local _r="${_lock#disabled:missing }"
            _rtag="requires ${_r}"
        elif [[ "$_lock" == "disabled"* ]]; then
            _rtag="disabled by config"
        fi
        [[ ${#_rtag} -gt $max_tag_len ]] && max_tag_len=${#_rtag}
    done
    local name_col_width=$(( max_name_len + 2 ))

    _render_ms_menu() {
        local cols=80
        if command -v tput >/dev/null 2>&1; then
            cols="$(tput cols 2>/dev/null || echo 80)"
        fi
        local ind="${LOG_INDENT:-  }"
        printf '%s%s %s\n' "$ind" "${CLR_PRIMARY}${SYM_Q}${RESET}" "${BOLD}${prompt}${RESET}" >&2
        printf '%s  %s\n' "$ind" "${CLR_MUTED}space toggle · a select all · enter confirm${RESET}" >&2

        local avail_space=$(( cols - ${#ind} - 6 - name_col_width ))
        local desc_col_width
        if [[ $max_tag_len -gt 0 ]]; then
            desc_col_width=$(( avail_space - max_tag_len - 2 ))
        else
            desc_col_width=$(( avail_space - 2 ))
        fi
        [[ $desc_col_width -lt 20 ]] && desc_col_width=20

        local i
        for i in "${!_ms_items[@]}"; do
            local item="${_ms_items[$i]}"
            local lbl="${_ms_labels[$i]:-$item}"
            local desc="${_ms_descs[$i]:-}"
            local st="${_ms_states[$i]:-0}"
            local lock="${_ms_locks[$i]:-}"
            local radio_icon=""

            if [[ "$lock" == "disabled"* || "$lock" == "unsupported:"* ]]; then
                radio_icon="${CLR_MUTED}–${RESET}"
            elif [[ "$lock" == "installed:"* || "$lock" == "installed" ]]; then
                if [[ "$st" -eq 1 ]]; then
                    radio_icon="${CLR_MUTED}◇${RESET}"
                else
                    radio_icon="${CLR_MUTED}○${RESET}"
                fi
            elif [[ "$lock" == "required" || "$st" -eq 1 ]]; then
                radio_icon="${CLR_PRIMARY}●${RESET}"
            else
                radio_icon="${CLR_MUTED}○${RESET}"
            fi

            local raw_tag="" tag_fmt=""
            if [[ "$lock" == "required" ]]; then
                raw_tag="required"
                tag_fmt="${CLR_ACCENT}${raw_tag}${RESET}"
            elif [[ "$lock" == "installed:"* || "$lock" == "installed" ]]; then
                raw_tag="already installed"
                tag_fmt="${CLR_MUTED}${raw_tag}${RESET}"
            elif [[ "$lock" == "alt:"*" installed" ]]; then
                local alt_target="${lock#alt:}"
                alt_target="${alt_target% installed}"
                raw_tag="modern replacement for ${alt_target}"
                tag_fmt="${CLR_MUTED}${raw_tag}${RESET}"
            elif [[ "$lock" == "alt:"* ]]; then
                local alt_target="${lock#alt:}"
                raw_tag="alternative to ${alt_target}"
                tag_fmt="${CLR_MUTED}${raw_tag}${RESET}"
            elif [[ "$lock" == "unsupported:"* ]]; then
                local reason="${lock#unsupported:}"
                raw_tag="unavailable on ${reason}"
                tag_fmt="${CLR_WARN}${raw_tag}${RESET}"
            elif [[ "$lock" == "disabled:missing "* ]]; then
                local req_dep="${lock#disabled:missing }"
                raw_tag="requires ${req_dep}"
                tag_fmt="${CLR_MUTED}${raw_tag}${RESET}"
            elif [[ "$lock" == "disabled"* ]]; then
                raw_tag="disabled by config"
                tag_fmt="${CLR_MUTED}${raw_tag}${RESET}"
            fi

            local pad_len=$(( name_col_width - ${#lbl} ))
            [[ $pad_len -lt 1 ]] && pad_len=1
            local pad_spaces
            printf -v pad_spaces '%*s' "$pad_len" ""

            local cur_desc="$desc"
            if [[ -n "$cur_desc" ]]; then
                if [[ ${#cur_desc} -gt $desc_col_width ]]; then
                    cur_desc="${cur_desc:0:$((desc_col_width - 1))}…"
                fi
            fi

            local desc_spaces=""
            if [[ $max_tag_len -gt 0 ]]; then
                local desc_pad=$(( desc_col_width - ${#cur_desc} ))
                [[ $desc_pad -lt 1 ]] && desc_pad=1
                printf -v desc_spaces '%*s' "$desc_pad" ""
            fi

            if [[ $i -eq $selected ]]; then
                if [[ "$lock" == "disabled"* || "$lock" == "unsupported:"* ]]; then
                    local desc_fmt=""
                    [[ -n "$cur_desc" ]] && desc_fmt="${CLR_MUTED}${cur_desc}${RESET}"
                    printf '%s  %s  %s%s%s%s%s\n' "$ind" "$radio_icon" "${BOLD}${CLR_MUTED}${lbl}${RESET}" "$pad_spaces" "$desc_fmt" "$desc_spaces" "$tag_fmt" >&2
                else
                    local desc_fmt=""
                    [[ -n "$cur_desc" ]] && desc_fmt="${CLR_TEXT}${cur_desc}${RESET}"
                    printf '%s  %s  %s%s%s%s%s\n' "$ind" "$radio_icon" "${BOLD}${CLR_PRIMARY}${lbl}${RESET}" "$pad_spaces" "$desc_fmt" "$desc_spaces" "$tag_fmt" >&2
                fi
            else
                local desc_fmt=""
                [[ -n "$cur_desc" ]] && desc_fmt="${CLR_MUTED}${cur_desc}${RESET}"
                printf '%s  %s  %s%s%s%s%s\n' "$ind" "$radio_icon" "${CLR_MUTED}${lbl}${RESET}" "$pad_spaces" "$desc_fmt" "$desc_spaces" "$tag_fmt" >&2
            fi
        done
    }

    # WINCH signal trap for window resizing
    _on_winch() {
        printf '\033[%dA\033[J' "$((total + 2))" >&2
        _render_ms_menu
    }
    trap '_on_winch' WINCH

    _render_ms_menu

    while true; do
        IFS= read -rsn1 key < /dev/tty 2>/dev/null || break
        if [[ "$key" == $'\x1b' ]]; then
            read -rsn2 -t 0.1 rest < /dev/tty 2>/dev/null || rest=""
            key+="$rest"
        fi

        case "$key" in
            $'\x1b[A'|k|K)
                selected=$(( (selected - 1 + total) % total ))
                ;;
            $'\x1b[B'|j|J)
                selected=$(( (selected + 1) % total ))
                ;;
            " "|x|X)
                local cur_lock="${_ms_locks[$selected]:-}"
                if [[ "$cur_lock" != "required" && "$cur_lock" != "installed:"* && "$cur_lock" != "unsupported:"* && "$cur_lock" != "disabled"* ]]; then
                    if [[ "${_ms_states[$selected]:-0}" -eq 1 ]]; then
                        _ms_states[$selected]=0
                    else
                        _ms_states[$selected]=1
                    fi
                fi
                ;;
            a|A)
                local all_toggleable_checked=1
                local j
                for j in "${!_ms_items[@]}"; do
                    local j_lock="${_ms_locks[$j]:-}"
                    if [[ "$j_lock" != "required" && "$j_lock" != "installed:"* && "$j_lock" != "unsupported:"* && "$j_lock" != "disabled"* ]]; then
                        if [[ "${_ms_states[$j]:-0}" -ne 1 ]]; then
                            all_toggleable_checked=0
                            break
                        fi
                    fi
                done
                for j in "${!_ms_items[@]}"; do
                    local j_lock="${_ms_locks[$j]:-}"
                    if [[ "$j_lock" != "required" && "$j_lock" != "installed:"* && "$j_lock" != "unsupported:"* && "$j_lock" != "disabled"* ]]; then
                        if [[ $all_toggleable_checked -eq 1 ]]; then
                            _ms_states[$j]=0
                        else
                            _ms_states[$j]=1
                        fi
                    fi
                done
                ;;
            "")
                break
                ;;
        esac

        printf '\033[%dA' "$((total + 2))" >&2
        _render_ms_menu
    done

    trap - WINCH

    printf '\033[?25h' >&2
    printf '\033[%dA\033[J' "$((total + 2))" >&2

    local chosen_ids=()
    local chosen_lbls=()
    local k
    for k in "${!_ms_items[@]}"; do
        local lk="${_ms_locks[$k]:-}"
        local s="${_ms_states[$k]:-0}"
        if [[ "$lk" == "required" || "$s" -eq 1 ]]; then
            if [[ "$lk" != "unsupported:"* && "$lk" != "disabled:"* ]]; then
                chosen_ids+=("${_ms_items[$k]}")
                chosen_lbls+=("${_ms_labels[$k]:-${_ms_items[$k]}}")
            fi
        fi
    done

    local summary_str="${chosen_lbls[*]:-none}"
    summary_str="${summary_str// /, }"
    local ind="${LOG_INDENT:-  }"
    printf '%s%s %s: %s %s\n' "$ind" "${CLR_SUCCESS}${SYM_OK}${RESET}" "${prompt}" "${CLR_TEXT}${summary_str}${RESET}" "${CLR_MUTED}(${#chosen_ids[@]} selected)${RESET}" >&2

    printf '%s ' "${chosen_ids[@]}"
}

_ui_phase() {
    local num="$1" total="$2" title="$3"
    if [[ -t 1 && -z "${NO_COLOR:-}" ]]; then
        printf '\n%s[%s/%s]%s %s%s%s\n\n' "${CLR_MUTED}" "$num" "$total" "${RESET}" "${CLR_TEXT}${BOLD}" "$title" "${RESET}" >&2
    else
        printf '\n[%s/%s] %s\n\n' "$num" "$total" "$title" >&2
    fi
}

_get_remediation_hint() {
    local err_text="$1"
    if [[ "$err_text" == *"lock"* || "$err_text" == *"Could not get lock"* ]]; then
        printf 'Package manager lock busy. Wait for background update or clear stale lock.'
    elif [[ "$err_text" == *"404"* || "$err_text" == *"Not Found"* ]]; then
        printf 'Asset not found. Check release URL and target architecture.'
    elif [[ "$err_text" == *"403"* || "$err_text" == *"rate limit"* || "$err_text" == *"Rate limit"* ]]; then
        printf 'GitHub API rate limit exceeded. Set GITHUB_TOKEN to proceed.'
    elif [[ "$err_text" == *"Permission denied"* || "$err_text" == *"permission denied"* ]]; then
        printf 'Permission denied. Run with sudo or fix target path permissions.'
    elif [[ "$err_text" == *"checksum mismatch"* || "$err_text" == *"Checksum mismatch"* ]]; then
        printf 'Checksum mismatch. Downloaded archive is corrupted or modified.'
    fi
}

_extract_last_error() {
    local log_file="$1"
    [[ ! -f "$log_file" ]] && return 0
    local line=""
    line="$(grep -v '^[[:space:]]*$' "$log_file" 2>/dev/null | tail -n 1 || true)"
    line="${line#"${line%%[![:space:]]*}"}"
    line="${line%"${line##*[![:space:]]}"}"
    if [[ ${#line} -gt 120 ]]; then
        line="${line:0:117}..."
    fi
    printf '%s' "$line"
}

_run_with_spinner() {
    local label="$1"
    shift
    local ind="${SPINNER_INDENT:-  }"
    _LAST_CMD_ERROR=""

    if [[ "${VERBOSE:-false}" == true || ! -t 2 ]]; then
        log_info "$label"
        local rc=0
        local cmd_log
        cmd_log="$(mktemp "${TMPDIR:-/tmp}/dotfiles_cmd_XXXXXX.log" 2>/dev/null || mktemp)"
        _TRACKED_TMP_FILES+=("$cmd_log")
        if [[ "${VERBOSE:-false}" == true ]]; then
            "$@" 2>&1 | tee "$cmd_log" || rc=${PIPESTATUS[0]}
        else
            "$@" > "$cmd_log" 2>&1 || rc=$?
        fi
        if [[ $rc -ne 0 ]]; then
            _LAST_CMD_ERROR="$(_extract_last_error "$cmd_log")"
            if [[ -n "$_LAST_CMD_ERROR" && "${VERBOSE:-false}" != true ]]; then
                printf '%s  %s %s\n' "$ind" "${CLR_ERROR}↳${RESET}" "${CLR_MUTED}${_LAST_CMD_ERROR}${RESET}" >&2
                local rhint
                rhint="$(_get_remediation_hint "$_LAST_CMD_ERROR")"
                [[ -n "$rhint" ]] && printf '%s    %s %s\n' "$ind" "${CLR_WARN}hint:${RESET}" "${CLR_MUTED}${rhint}${RESET}" >&2
            fi
        fi
        rm -f "$cmd_log" 2>/dev/null || true
        return $rc
    fi

    printf '\033[?25l' >&2
    local spin_chars=("⠋" "⠙" "⠹" "⠸" "⠼" "⠴" "⠦" "⠧" "⠇" "⠏")
    local num_frames=${#spin_chars[@]}
    local i=0
    local pid

    local cmd_log
    cmd_log="$(mktemp "${TMPDIR:-/tmp}/dotfiles_cmd_XXXXXX.log" 2>/dev/null || mktemp)"
    _TRACKED_TMP_FILES+=("$cmd_log")

    "$@" > "$cmd_log" 2>&1 &
    pid=$!

    local start_time=$SECONDS
    local cols=80
    if command -v tput >/dev/null 2>&1; then
        cols="$(tput cols 2>/dev/null || echo 80)"
    fi
    local max_lbl=$(( cols - 18 ))
    [[ $max_lbl -lt 20 ]] && max_lbl=20

    local base_label="$label"
    local meta_suffix=""
    local meta_regex='^(.*)[[:space:]]+\(([^)]+)\)$'
    if [[ "$label" =~ $meta_regex ]]; then
        base_label="${BASH_REMATCH[1]}"
        meta_suffix="${BASH_REMATCH[2]}"
    fi

    local display_base="$base_label"
    if [[ ${#display_base} -gt $max_lbl ]]; then
        display_base="${display_base:0:$((max_lbl - 3))}..."
    fi

    local last_elapsed=-1
    local elapsed_str=""
    while kill -0 "$pid" 2>/dev/null; do
        local elapsed=$(( SECONDS - start_time ))
        if [[ $elapsed -ne $last_elapsed ]]; then
            last_elapsed=$elapsed
            if [[ -n "$meta_suffix" ]]; then
                elapsed_str=" ${CLR_MUTED}(${meta_suffix}, ${elapsed}s)${RESET}"
            else
                elapsed_str=" ${CLR_MUTED}(${elapsed}s)${RESET}"
            fi
        fi
        local frame="${spin_chars[i % num_frames]}"
        printf '\r\033[2K%s%s %s%s' "$ind" "${CLR_PRIMARY}${frame}${RESET}" "${CLR_TEXT}${display_base}${RESET}" "$elapsed_str" >&2
        i=$((i + 1))
        sleep 0.08 2>/dev/null || sleep 1
    done

    local rc=0
    wait "$pid" || rc=$?
    local total_time=$(( SECONDS - start_time ))
    printf '\033[?25h' >&2

    local final_meta=""
    if [[ -n "$meta_suffix" ]]; then
        final_meta="${CLR_MUTED}(${meta_suffix}, ${total_time}s)${RESET}"
    else
        final_meta="${CLR_MUTED}(${total_time}s)${RESET}"
    fi

    if [[ $rc -eq 0 ]]; then
        printf '\r\033[2K%s%s %s %s\n' "$ind" "${CLR_SUCCESS}${SYM_OK}${RESET}" "${display_base}" "${final_meta}" >&2
    else
        printf '\r\033[2K%s%s %s %s\n' "$ind" "${CLR_ERROR}${BOLD}${SYM_FAIL}${RESET}" "${CLR_ERROR}${display_base} (failed)${RESET}" "${final_meta}" >&2
        _LAST_CMD_ERROR="$(_extract_last_error "$cmd_log")"
        if [[ -n "$_LAST_CMD_ERROR" ]]; then
            printf '%s  %s %s\n' "$ind" "${CLR_ERROR}↳${RESET}" "${CLR_MUTED}${_LAST_CMD_ERROR}${RESET}" >&2
            local rhint
            rhint="$(_get_remediation_hint "$_LAST_CMD_ERROR")"
            [[ -n "$rhint" ]] && printf '%s    %s %s\n' "$ind" "${CLR_WARN}hint:${RESET}" "${CLR_MUTED}${rhint}${RESET}" >&2
        fi
    fi
    rm -f "$cmd_log" 2>/dev/null || true
    return $rc
}

# Render final summary report card
_ui_render_summary() {
    local total_time="${1:-0}"
    local installed_count="${2:-0}"
    local backup_count="${3:-0}"
    local failed_count="${#_FAILED_PACKAGES[@]}"

    _ui_header "Setup Summary"
    printf '  %-20s %s\n' "Execution time:" "${total_time}s"
    printf '  %-20s %s\n' "Packages:" "${installed_count}"
    if [[ $backup_count -gt 0 && -n "${BACKUP_DIR:-}" ]]; then
        printf '  %-20s %s %s\n' "Backups:" "${backup_count}" "${CLR_MUTED}(${BACKUP_DIR})${RESET}"
    else
        printf '  %-20s %s\n' "Backups:" "${backup_count}"
    fi

    if [[ $failed_count -gt 0 ]]; then
        printf '  %-20s %s\n' "Failures:" "${CLR_ERROR}${failed_count}${RESET}"
        local fp
        for fp in "${_FAILED_PACKAGES[@]}"; do
            local r="${_FAILURE_REASONS["$fp"]:-unknown error}"
            printf '    %s %s (%s)\n' "${CLR_ERROR}✗${RESET}" "${BOLD}${fp}${RESET}" "${CLR_MUTED}${r}${RESET}"
            local rhint
            rhint="$(_get_remediation_hint "$r")"
            [[ -n "$rhint" ]] && printf '      %s %s\n' "${CLR_WARN}↳ hint:${RESET}" "${CLR_MUTED}${rhint}${RESET}"
        done
    else
        printf '  %-20s %s\n' "Status:" "${CLR_SUCCESS}${BOLD}Completed successfully${RESET}"
    fi
    echo ""
}

# ── Module: src/parser.sh ──
# =============================================================================
#  PARSER ENGINE (Condition Grammar & INI Manifests)
# =============================================================================

_in_cond_list() {
    local target="$1" list_str="$2"
    [[ -z "$list_str" ]] && return 1
    local item ret=1 old_f="$-"
    set -f
    for item in ${list_str//,/ }; do
        item="${item#"${item%%[![:space:]]*}"}"; item="${item%"${item##*[![:space:]]}"}"
        if [[ "$item" == "$target" ]]; then
            ret=0
            break
        fi
    done
    [[ "$old_f" != *f* ]] && set +f
    return "$ret"
}

_check_cond_match() {
    local target="$1" list_str="$2"
    [[ -z "$list_str" ]] && return 1
    local clean_target="${target#arch:}"
    clean_target="${clean_target#profile:}"
    _in_cond_list "$target" "$list_str" || _in_cond_list "$clean_target" "$list_str"
}

# Evaluate cond field or cond: option. Returns 0 = proceed, 1 = skip.
_eval_cond() {
    local cond="$1" opts="${2:-}"
    [[ -z "$cond" ]] && cond="$(_get_opt cond "$opts")"
    [[ -z "$cond" ]] && return 0

    if [[ "${_CONF_CASCADE_DONE:-0}" -eq 0 && -d "${PACKAGES_DIR:-}" ]]; then
        _preload_all_manifests "$PACKAGES_DIR"
    fi

    local cond_override="${_CONF_PKG_KEYS["global:COND"]:-${COND:-}}"
    local dis_cond_override="${_CONF_PKG_KEYS["global:DISABLE_COND"]:-${DISABLE_COND:-}}"

    local c sys_arch _conds not_c
    sys_arch="$(_get_arch)"
    IFS=',' read -ra _conds <<< "$cond"
    for c in "${_conds[@]}"; do
        c="${c#"${c%%[![:space:]]*}"}"; c="${c%"${c##*[![:space:]]}"}"
        [[ -z "$c" ]] && continue

        if [[ "$c" == *"!"* ]]; then
            not_c="${c//!/}"
        else
            if [[ "$c" == "arch:"* ]]; then
                not_c="arch:!${c#arch:}"
            elif [[ "$c" == "profile:"* ]]; then
                not_c="profile:!${c#profile:}"
            else
                not_c="!$c"
            fi
        fi

        if _check_cond_match "$c" "$dis_cond_override" || _check_cond_match "$not_c" "$cond_override"; then
            return 1
        fi

        if _check_cond_match "$c" "$cond_override"; then
            continue
        fi

        local bare_c="$c"
        bare_c="${bare_c#profile:}"
        bare_c="${bare_c/profile:/}"

        case "$bare_c" in
            desktop|linux)                        [[ "$(_get_profile)" == "desktop" || "$(uname -s)" == Linux ]] || return 1 ;;
            '!desktop'|'!linux')                  [[ "$(_get_profile)" != "desktop" && "$(uname -s)" != Linux ]] || return 1 ;;
            wsl)                                  _is_wsl || return 1 ;;
            '!wsl')                               _is_wsl && return 1 ;;
            vps)                                  [[ "$(_get_profile)" == "vps" ]] || return 1 ;;
            '!vps')                               [[ "$(_get_profile)" != "vps" ]] || return 1 ;;
            container)                            _is_container || return 1 ;;
            '!container')                         _is_container && return 1 ;;
            arch:x86_64|x86_64|arch:amd64|amd64)     [[ "$sys_arch" == x86_64 ]] || return 1 ;;
            arch:!x86_64|!x86_64|arch:!amd64|!amd64) [[ "$sys_arch" != x86_64 ]] || return 1 ;;
            arch:arm64|arm64|arch:aarch64|aarch64)   [[ "$sys_arch" == arm64 ]] || return 1 ;;
            arch:!arm64|!arm64|arch:!aarch64|!aarch64) [[ "$sys_arch" != arm64 ]] || return 1 ;;
            *)                                    log_warn "Unknown condition '$c'. Skipping package."; return 1 ;;
        esac
    done
    return 0
}

# Resolve the human-readable detected condition that caused a failure
_get_failed_cond_reason() {
    local cond="$1" opts="${2:-}"
    [[ -z "$cond" ]] && cond="$(_get_opt cond "$opts")"
    [[ -z "$cond" ]] && { printf 'unmet'; return 0; }

    local cond_override="${_CONF_PKG_KEYS["global:COND"]:-${COND:-}}"
    local dis_cond_override="${_CONF_PKG_KEYS["global:DISABLE_COND"]:-${DISABLE_COND:-}}"
    local sys_arch="$(_get_arch)"

    local c _conds not_c
    IFS=',' read -ra _conds <<< "$cond"
    for c in "${_conds[@]}"; do
        c="${c#"${c%%[![:space:]]*}"}"; c="${c%"${c##*[![:space:]]}"}"
        [[ -z "$c" ]] && continue

        if [[ "$c" == *"!"* ]]; then
            not_c="${c//!/}"
        else
            if [[ "$c" == "arch:"* ]]; then
                not_c="arch:!${c#arch:}"
            elif [[ "$c" == "profile:"* ]]; then
                not_c="profile:!${c#profile:}"
            else
                not_c="!$c"
            fi
        fi

        if _check_cond_match "$c" "$dis_cond_override" || _check_cond_match "$not_c" "$cond_override"; then
            printf '%s' "${c}"
            return 0
        fi

        if _check_cond_match "$c" "$cond_override"; then
            continue
        fi

        local bare_c="$c"
        bare_c="${bare_c#profile:}"
        bare_c="${bare_c/profile:/}"

        case "$bare_c" in
            desktop|linux)
                if [[ "$(_get_profile)" != "desktop" && "$(uname -s)" != Linux ]]; then
                    printf '%s' "$(_get_profile)"
                    return 0
                fi
                ;;
            '!desktop'|'!linux')
                if [[ "$(_get_profile)" == "desktop" || "$(uname -s)" == Linux ]]; then
                    printf '%s' "$(_get_profile)"
                    return 0
                fi
                ;;
            wsl)
                if ! _is_wsl; then
                    printf 'non-wsl'
                    return 0
                fi
                ;;
            '!wsl')
                if _is_wsl; then
                    printf 'wsl'
                    return 0
                fi
                ;;
            vps)
                if [[ "$(_get_profile)" != "vps" ]]; then
                    printf '%s' "$(_get_profile)"
                    return 0
                fi
                ;;
            '!vps')
                if [[ "$(_get_profile)" == "vps" ]]; then
                    printf 'vps'
                    return 0
                fi
                ;;
            container)
                if ! _is_container; then
                    printf 'host'
                    return 0
                fi
                ;;
            '!container')
                if _is_container; then
                    printf 'container'
                    return 0
                fi
                ;;
            arch:x86_64|x86_64|arch:amd64|amd64)
                if [[ "$sys_arch" != x86_64 ]]; then
                    printf '%s' "$sys_arch"
                    return 0
                fi
                ;;
            arch:!x86_64|!x86_64|arch:!amd64|!amd64)
                if [[ "$sys_arch" == x86_64 ]]; then
                    printf '%s' "$sys_arch"
                    return 0
                fi
                ;;
            arch:arm64|arm64|arch:aarch64|aarch64)
                if [[ "$sys_arch" != arm64 ]]; then
                    printf '%s' "$sys_arch"
                    return 0
                fi
                ;;
            arch:!arm64|!arm64|arch:!aarch64|!aarch64)
                if [[ "$sys_arch" == arm64 ]]; then
                    printf '%s' "$sys_arch"
                    return 0
                fi
                ;;
            *)
                printf '%s' "$c"
                return 0
                ;;
        esac
    done
    printf 'unmet'
}

# Prompt user for confirmation during interactive execution.


# ---------------------------------------------------------------------------
# _collect_bashrc_snippets CONF
# Pass 2 of packages.conf: collect [bashrc]...[/bashrc] blocks
# only for groups that are in INSTALL_GROUPS (or all if empty).
# ---------------------------------------------------------------------------
_preload_groups_conf() {
    [[ "$_GROUPS_LOADED" -eq 1 ]] && return 0
    _GROUPS_LOADED=1
    local groups_conf="$PACKAGES_DIR/_groups.conf"
    if [[ ! -f "$groups_conf" ]]; then
        local gdir
        for gdir in "$PACKAGES_DIR"/*; do
            [[ -d "$gdir" ]] && _GROUPS_LIST+=("$(basename "$gdir")")
        done
        return 0
    fi

    local current_grp="" raw_line line
    while IFS= read -r raw_line || [[ -n "$raw_line" ]]; do
        line="${raw_line#"${raw_line%%[![:space:]]*}"}"
        line="${line%"${line##*[![:space:]]}"}"
        [[ -z "$line" || "$line" == '#'* ]] && continue
        if [[ "$line" =~ ^\[group:([a-zA-Z0-9_.-]+) ]]; then
            current_grp="${BASH_REMATCH[1]}"
            _GROUPS_LIST+=("$current_grp")
            continue
        fi
        if [[ -n "$current_grp" && "$line" == *"="* ]]; then
            local k="${line%%=*}" v="${line#*=}"
            k="${k#"${k%%[![:space:]]*}"}"; k="${k%"${k##*[![:space:]]}"}"
            v="${v#"${v%%[![:space:]]*}"}"; v="${v%"${v##*[![:space:]]}"}"
            if [[ "$k" == "description" ]]; then
                _GROUP_DESCS["$current_grp"]="$v"
            elif [[ "$k" == "packages" ]]; then
                _GROUP_PACKAGES_MAP["$current_grp"]="$v"
            elif [[ "$k" == "optional" ]]; then
                _GROUP_OPTIONAL["$current_grp"]="$v"
            fi
        fi
    done < "$groups_conf"
}

_get_groups() {
    _preload_groups_conf
    if [[ ${#_GROUPS_LIST[@]} -gt 0 ]]; then
        printf '%s\n' "${_GROUPS_LIST[@]}"
    fi
}

_get_group_meta() {
    _preload_groups_conf
    case "$2" in
        description) printf '%s' "${_GROUP_DESCS["$1"]:-}" ;;
        packages)    printf '%s' "${_GROUP_PACKAGES_MAP["$1"]:-}" ;;
        optional)    printf '%s' "${_GROUP_OPTIONAL["$1"]:-true}" ;;
    esac
}

_get_group_packages() {
    local gname="$1"
    local pkgs_str="$(_get_group_meta "$gname" "packages")"
    if [[ -n "$pkgs_str" ]]; then
        local p
        IFS=',' read -ra p_arr <<< "$pkgs_str"
        for p in "${p_arr[@]}"; do
            p="${p#"${p%%[![:space:]]*}"}"; p="${p%"${p##*[![:space:]]}"}"
            [[ -n "$p" ]] && printf '%s\n' "$p"
        done
    else
        local conf_file
        for conf_file in "$PACKAGES_DIR/$gname"/*.conf; do
            [[ -f "$conf_file" ]] && basename "$conf_file" .conf
        done
    fi
}

_collect_bashrc_snippets() {
    local pdir="${1:-$PACKAGES_DIR}"
    [[ ! -d "$pdir" ]] && return 0
    _preload_all_manifests "$pdir"

    if [[ "${_CONF_BASHRC_DIS["global"]:-0}" -ne 1 && -n "${_CONF_BASHRC_BUF["global"]:-}" ]]; then
        printf '%s\n' "${_CONF_BASHRC_BUF["global"]}"
    fi

    local group pkg
    while IFS= read -r group; do
        [[ -z "$group" ]] && continue
        _group_selected "$group" || continue

        while IFS= read -r pkg; do
            [[ -z "$pkg" ]] && continue
            local conf_file="$pdir/$group/$pkg.conf"
            [[ ! -f "$conf_file" ]] && continue

            if _package_is_active "$conf_file"; then
                printf '%s' "${_CONF_BASHRC["$conf_file"]:-}"
            fi
        done < <(_get_group_packages "$group")
    done < <(_get_groups)
}



# ---------------------------------------------------------------------------
# Config-driven optional package resolution
# ---------------------------------------------------------------------------
_should_install_optional() {
    local pkg="$1" desc="$2" is_rec="${3:-false}" is_alt="${4:-false}" alt_target="${5:-}"

    # 1. Explicit package allow-list
    local p
    for p in "${OPTIONAL_PACKAGES[@]:-}"; do
        [[ "$p" == "$pkg" ]] && return 0
    done

    # 2. Unanswered: check TTY for interactive prompt
    if [[ -t 0 || -t 1 || -t 2 || -c /dev/tty ]] && [[ "$DRY_RUN" == false && "${NON_INTERACTIVE:-false}" == false ]]; then
        local msg="Install optional package '${pkg}'?"
        if [[ "$is_alt" == true ]]; then
            msg="Install alternative package '${pkg}' ('${alt_target}' is installed)?"
        fi
        local PROMPT_INDENT="    "
        _prompt_confirm "$msg" "$is_rec"
        return $?
    fi

    # 3. Unanswered headless default: recommended packages install automatically
    [[ "$is_rec" == true ]] && return 0 || return 1
}

_group_selected() {
    local gname="$1"
    if [[ ${#INSTALL_GROUPS[@]} -gt 0 ]]; then
        local g
        for g in "${INSTALL_GROUPS[@]}"; do
            [[ "$g" == "$gname" ]] && return 0
        done
        return 1
    fi

    local is_opt="$(_get_group_meta "$gname" "optional")"
    if [[ "$is_opt" == "false" || "$gname" == "core" ]]; then
        return 0
    fi
    return 1
}

_parse_section_header() {
    local raw_header="$1"
    local -n _out_type="$2"
    local -n _out_ident="$3"
    local -n _out_mod="$4"
    local -n _out_valid="$5"

    local l_type="" l_ident="" l_mod="append" l_valid=0

    local header="${raw_header#"${raw_header%%[![:space:]]*}"}"
    header="${header%"${header##*[![:space:]]}"}"
    if [[ -z "$header" ]]; then
        _out_type=""
        _out_ident=""
        _out_mod="append"
        _out_valid=1
        return 0
    fi

    local parts=()
    IFS=':' read -ra parts <<< "$header"
    local n=${#parts[@]}

    if [[ $n -eq 0 ]]; then
        _out_type=""
        _out_ident=""
        _out_mod="append"
        _out_valid=1
        return 0
    fi

    case "${parts[0]}" in
        package|config|bashrc|template|group) l_type="${parts[0]}" ;;
        *)
            _out_type=""
            _out_ident=""
            _out_mod="append"
            _out_valid=1
            return 0
            ;;
    esac

    if [[ "$l_type" == "template" ]]; then
        if [[ $n -eq 1 ]]; then
            l_ident=""
            l_mod="append"
        elif [[ $n -eq 2 ]]; then
            l_ident="${parts[1]}"
            l_mod="append"
        else
            l_ident="${parts[1]}"
            l_mod="${parts[*]:2}"
            l_valid=0
        fi
    else
        if [[ $n -eq 1 ]]; then
            l_ident=""
            l_mod="append"
        elif [[ $n -eq 2 ]]; then
            local p1="${parts[1]}"
            case "$p1" in
                append|override|disable|once)
                    l_ident=""
                    l_mod="$p1"
                    ;;
                *)
                    l_ident="$p1"
                    l_mod="append"
                    ;;
            esac
        elif [[ $n -eq 3 ]]; then
            local p1="${parts[1]}"
            local p2="${parts[2]}"
            case "$p2" in
                append|override|disable|once)
                    l_ident="$p1"
                    l_mod="$p2"
                    ;;
                *)
                    l_ident="$p1"
                    l_mod="$p2"
                    l_valid=1
                    ;;
            esac
        else
            l_valid=1
        fi
        l_ident="${l_ident%.conf}"
        l_ident="${l_ident#.}"
        if [[ "$l_ident" == *config && "$l_ident" != "config" && "$l_ident" != */* ]]; then
            l_ident="${l_ident%config}"
        fi
    fi

    _out_type="$l_type"
    _out_ident="$l_ident"
    _out_mod="$l_mod"
    _out_valid="$l_valid"
}


_clear_pkg_keys() {
    local target="$1"
    local k
    if [[ ${#_CONF_PKG_KEYS[@]} -gt 0 ]]; then
        for k in "${!_CONF_PKG_KEYS[@]}"; do
            if [[ "$k" == "${target}:"* ]]; then
                unset "_CONF_PKG_KEYS[$k]"
            fi
        done
    fi
}

_parse_single_conf_file() {
    local file="$1"
    local default_pkg="$2"
    [[ ! -f "$file" ]] && return 0

    local cur_type="" cur_ident="" cur_mod="append"
    local cur_tmpl_buf="" in_tmpl=false
    local raw_line line

    while IFS= read -r raw_line || [[ -n "$raw_line" ]]; do
        line="${raw_line#"${raw_line%%[![:space:]]*}"}"
        line="${line%"${line##*[![:space:]]}"}"

        if [[ "$line" =~ ^\[(.*)\]$ ]]; then
            local header="${BASH_REMATCH[1]}"
            local sec_type="" sec_ident="" sec_mod="" is_valid=0
            _parse_section_header "$header" sec_type sec_ident sec_mod is_valid

            if [[ "$is_valid" -eq 0 ]]; then
                if [[ "$in_tmpl" == true ]]; then
                    local t_target="${cur_ident:-$default_pkg}"
                    local formatted_tmpl="$cur_tmpl_buf"
                    if [[ "$formatted_tmpl" != *"# target:"* && "$formatted_tmpl" != "#target:"* ]]; then
                        formatted_tmpl="# target: ${cur_ident:-$default_pkg} flags: ${cur_mod:-append}"$'\n'"$formatted_tmpl"
                    fi
                    if [[ "${_CONF_TMPL_DIS["$t_target"]:-0}" -ne 1 && "${_CONF_TMPL_DIS["$default_pkg"]:-0}" -ne 1 ]]; then
                        _CONF_TMPL_BUF["$t_target"]+="${formatted_tmpl}__TMPL_SEP__"
                        if [[ "$t_target" != "$default_pkg" && -n "$default_pkg" ]]; then
                            _CONF_TMPL_BUF["$default_pkg"]+="${formatted_tmpl}__TMPL_SEP__"
                        fi
                    fi
                    cur_tmpl_buf=""
                    in_tmpl=false
                fi

                cur_type="$sec_type"
                cur_ident="${sec_ident:-$default_pkg}"
                cur_mod="$sec_mod"

                if [[ "$cur_type" == "template" ]]; then
                    in_tmpl=true
                    if [[ "$cur_mod" == *"override"* ]]; then
                        _CONF_TMPL_BUF["$cur_ident"]=""
                        _CONF_TMPL_DIS["$cur_ident"]=0
                    elif [[ "$cur_mod" == *"disable"* ]]; then
                        _CONF_TMPL_BUF["$cur_ident"]=""
                        _CONF_TMPL_DIS["$cur_ident"]=1
                    else
                        _CONF_TMPL_DIS["$cur_ident"]=0
                    fi
                elif [[ "$cur_type" == "package" || "$cur_type" == "config" ]]; then
                    if [[ "$cur_mod" == "override" ]]; then
                        _clear_pkg_keys "$cur_ident"
                        _CONF_PKG_DISABLED["$cur_ident"]=0
                    elif [[ "$cur_mod" == "disable" ]]; then
                        _clear_pkg_keys "$cur_ident"
                        _CONF_PKG_DISABLED["$cur_ident"]=1
                    elif [[ "$cur_mod" == "append" ]]; then
                        _CONF_PKG_DISABLED["$cur_ident"]=0
                    fi
                elif [[ "$cur_type" == "bashrc" ]]; then
                    if [[ "$cur_mod" == "override" ]]; then
                        _CONF_BASHRC_BUF["$cur_ident"]=""
                        _CONF_BASHRC_DIS["$cur_ident"]=0
                    elif [[ "$cur_mod" == "disable" ]]; then
                        _CONF_BASHRC_BUF["$cur_ident"]=""
                        _CONF_BASHRC_DIS["$cur_ident"]=1
                    elif [[ "$cur_mod" == "append" ]]; then
                        _CONF_BASHRC_DIS["$cur_ident"]=0
                    fi
                fi
                continue
            fi
        fi

        if [[ "$in_tmpl" == true ]]; then
            cur_tmpl_buf+="${raw_line}"$'\n'
            continue
        fi

        if [[ "$cur_type" == "bashrc" ]]; then
            if [[ "${_CONF_BASHRC_DIS["$cur_ident"]:-0}" -ne 1 ]]; then
                _CONF_BASHRC_BUF["$cur_ident"]+="${raw_line}"$'\n'
            fi
            continue
        fi

        if [[ "$cur_type" == "package" || "$cur_type" == "config" ]]; then
            [[ -z "$line" || "$line" == '#'* ]] && continue
            if [[ "$line" == *"="* ]]; then
                local key="${line%%=*}" val="${line#*=}"
                key="${key#"${key%%[![:space:]]*}"}"; key="${key%"${key##*[![:space:]]}"}"
                val="${val#"${val%%[![:space:]]*}"}"; val="${val%"${val##*[![:space:]]}"}"
                if [[ "$val" == "!delete" ]]; then
                    unset "_CONF_PKG_KEYS[${cur_ident}:${key}]"
                else
                    _CONF_PKG_KEYS["${cur_ident}:${key}"]="$val"
                fi
            fi
        fi
    done < "$file"

    if [[ "$in_tmpl" == true ]]; then
        local t_target="${cur_ident:-$default_pkg}"
        local formatted_tmpl="$cur_tmpl_buf"
        if [[ "$formatted_tmpl" != *"# target:"* && "$formatted_tmpl" != "#target:"* ]]; then
            formatted_tmpl="# target: ${cur_ident:-$default_pkg} flags: ${cur_mod:-append}"$'\n'"$formatted_tmpl"
        fi
        if [[ "${_CONF_TMPL_DIS["$t_target"]:-0}" -ne 1 && "${_CONF_TMPL_DIS["$default_pkg"]:-0}" -ne 1 ]]; then
            _CONF_TMPL_BUF["$t_target"]+="${formatted_tmpl}__TMPL_SEP__"
            if [[ "$t_target" != "$default_pkg" && -n "$default_pkg" ]]; then
                _CONF_TMPL_BUF["$default_pkg"]+="${formatted_tmpl}__TMPL_SEP__"
            fi
        fi
    fi
}

_get_pkg_prop() {
    local pkg="$1" target_key="$2" default_val="$3"
    shift 3
    local key
    for key in "$@"; do
        if [[ -n "${_CONF_PKG_KEYS["${pkg}:${key}"]+x}" ]]; then
            printf '%s' "${_CONF_PKG_KEYS["${pkg}:${key}"]}"
            return 0
        elif [[ -n "${_CONF_PKG_KEYS["${target_key}:${key}"]+x}" ]]; then
            printf '%s' "${_CONF_PKG_KEYS["${target_key}:${key}"]}"
            return 0
        fi
    done
    printf '%s' "$default_val"
}

_finalize_conf_caches() {
    local pdir="$1"
    [[ ! -d "$pdir" ]] && return 0

    # Pre-index extra hook keys once across all packages instead of O(N*K) scan per package
    declare -A _pkg_hooks=()
    local k
    if [[ ${#_CONF_PKG_KEYS[@]} -gt 0 ]]; then
        for k in "${!_CONF_PKG_KEYS[@]}"; do
            if [[ "$k" == *":cmd."* || "$k" == *":cmd" ]]; then
                local prefix="${k%:*}"
                local prop_name="${k#*:}"
                local prop_val="${_CONF_PKG_KEYS["$k"]}"
                _pkg_hooks["$prefix"]+="${prop_name}:\"${prop_val//\"/\\\"}\" "
            fi
        done
    fi

    local conf_file
    for conf_file in "$pdir"/*/*.conf; do
        [[ ! -f "$conf_file" ]] && continue
        local pkg group target_key
        pkg="$(basename "$conf_file" .conf)"
        group="$(basename "$(dirname "$conf_file")")"
        target_key="${group}/${pkg}"

        local p_name="${_CONF_PKG_KEYS["${pkg}:name"]:-${_CONF_PKG_KEYS["${target_key}:name"]:-$pkg}}"
        local p_bin="${_CONF_PKG_KEYS["${pkg}:binaries"]:-${_CONF_PKG_KEYS["${target_key}:binaries"]:-${_CONF_PKG_KEYS["${pkg}:bin"]:-${_CONF_PKG_KEYS["${target_key}:bin"]:-$pkg}}}}"
        local p_desc="${_CONF_PKG_KEYS["${pkg}:description"]:-${_CONF_PKG_KEYS["${target_key}:description"]:-${_CONF_PKG_KEYS["${pkg}:desc"]:-${_CONF_PKG_KEYS["${target_key}:desc"]:-}}}}"
        local p_scope="${_CONF_PKG_KEYS["${pkg}:system"]:-${_CONF_PKG_KEYS["${target_key}:system"]:-${_CONF_PKG_KEYS["${pkg}:scope"]:-${_CONF_PKG_KEYS["${target_key}:scope"]:-system}}}}"

        local apt_pkg="${_CONF_PKG_KEYS["${pkg}:apt"]:-${_CONF_PKG_KEYS["${target_key}:apt"]:-}}"
        local dnf_pkg="${_CONF_PKG_KEYS["${pkg}:dnf"]:-${_CONF_PKG_KEYS["${target_key}:dnf"]:-}}"
        local pacman_pkg="${_CONF_PKG_KEYS["${pkg}:pacman"]:-${_CONF_PKG_KEYS["${target_key}:pacman"]:-}}"
        local apk_pkg="${_CONF_PKG_KEYS["${pkg}:apk"]:-${_CONF_PKG_KEYS["${target_key}:apk"]:-}}"
        local mise_spec="${_CONF_PKG_KEYS["${pkg}:mise"]:-${_CONF_PKG_KEYS["${target_key}:mise"]:-}}"
        local uv_spec="${_CONF_PKG_KEYS["${pkg}:uv"]:-${_CONF_PKG_KEYS["${target_key}:uv"]:-}}"
        local cargo_spec="${_CONF_PKG_KEYS["${pkg}:cargo"]:-${_CONF_PKG_KEYS["${target_key}:cargo"]:-}}"
        local go_spec="${_CONF_PKG_KEYS["${pkg}:go"]:-${_CONF_PKG_KEYS["${target_key}:go"]:-}}"
        local bun_spec="${_CONF_PKG_KEYS["${pkg}:bun"]:-${_CONF_PKG_KEYS["${target_key}:bun"]:-}}"
        local npm_spec="${_CONF_PKG_KEYS["${pkg}:npm"]:-${_CONF_PKG_KEYS["${target_key}:npm"]:-}}"
        local flatpak_spec="${_CONF_PKG_KEYS["${pkg}:flatpak"]:-${_CONF_PKG_KEYS["${target_key}:flatpak"]:-}}"
        local brew_spec="${_CONF_PKG_KEYS["${pkg}:brew"]:-${_CONF_PKG_KEYS["${target_key}:brew"]:-}}"
        local cmd_val="${_CONF_PKG_KEYS["${pkg}:cmd"]:-${_CONF_PKG_KEYS["${target_key}:cmd"]:-}}"
        local cond_val="${_CONF_PKG_KEYS["${pkg}:cond"]:-${_CONF_PKG_KEYS["${target_key}:cond"]:-}}"
        local rec_val="${_CONF_PKG_KEYS["${pkg}:recommended"]:-${_CONF_PKG_KEYS["${target_key}:recommended"]:-${_CONF_PKG_KEYS["${pkg}:rec"]:-${_CONF_PKG_KEYS["${target_key}:rec"]:-}}}}"
        local alt_val="${_CONF_PKG_KEYS["${pkg}:alt"]:-${_CONF_PKG_KEYS["${target_key}:alt"]:-}}"
        local needs_val="${_CONF_PKG_KEYS["${pkg}:needs"]:-${_CONF_PKG_KEYS["${target_key}:needs"]:-}}"
        local opt_val="${_CONF_PKG_KEYS["${pkg}:optional"]:-${_CONF_PKG_KEYS["${target_key}:optional"]:-}}"
        local dis_val="${_CONF_PKG_KEYS["${pkg}:disabled"]:-${_CONF_PKG_KEYS["${target_key}:disabled"]:-}}"
        local p_install="${_CONF_PKG_KEYS["${pkg}:install"]:-${_CONF_PKG_KEYS["${target_key}:install"]:-}}"
        local p_opts="${_CONF_PKG_KEYS["${pkg}:options"]:-${_CONF_PKG_KEYS["${target_key}:options"]:-}}"

        local extra_inst_specs="${_pkg_hooks["$target_key"]:-}${_pkg_hooks["$pkg"]:-}"

        local inst_specs=""
        [[ -n "$apt_pkg" ]] && inst_specs+="apt:${apt_pkg} "
        [[ -n "$dnf_pkg" ]] && inst_specs+="dnf:${dnf_pkg} "
        [[ -n "$pacman_pkg" ]] && inst_specs+="pacman:${pacman_pkg} "
        [[ -n "$apk_pkg" ]] && inst_specs+="apk:${apk_pkg} "
        [[ -n "$mise_spec" ]] && inst_specs+="mise:\"${mise_spec}\" "
        [[ -n "$uv_spec" ]] && inst_specs+="uv:\"${uv_spec}\" "
        [[ -n "$cargo_spec" ]] && inst_specs+="cargo:\"${cargo_spec}\" "
        [[ -n "$go_spec" ]] && inst_specs+="go:\"${go_spec}\" "
        [[ -n "$bun_spec" ]] && inst_specs+="bun:\"${bun_spec}\" "
        [[ -n "$npm_spec" ]] && inst_specs+="npm:\"${npm_spec}\" "
        [[ -n "$flatpak_spec" ]] && inst_specs+="flatpak:\"${flatpak_spec}\" "
        [[ -n "$brew_spec" ]] && inst_specs+="brew:\"${brew_spec}\" "
        [[ -n "$cmd_val" ]] && inst_specs+="cmd:\"${cmd_val}\" "
        [[ -n "$extra_inst_specs" ]] && inst_specs+="${extra_inst_specs}"
        [[ -n "$p_install" ]] && inst_specs+="${p_install} "

        local opt_specs=""
        [[ -n "$cond_val" ]] && opt_specs+="cond:${cond_val} "
        [[ -n "$alt_val" ]] && opt_specs+="alt:${alt_val} "
        [[ -n "$needs_val" ]] && opt_specs+="needs:${needs_val} "
        [[ "$opt_val" == true ]] && opt_specs+="optional:true "
        if [[ "$rec_val" == true ]]; then
            opt_specs+="recommended:true "
        elif [[ -n "$rec_val" && "$rec_val" != false ]]; then
            if _eval_cond "$rec_val"; then
                opt_specs+="recommended:true "
            fi
        fi
        [[ "$dis_val" == true || "${_CONF_PKG_DISABLED["$pkg"]:-0}" -eq 1 || "${_CONF_PKG_DISABLED["$target_key"]:-0}" -eq 1 ]] && opt_specs+="disabled:true "
        [[ -n "$p_opts" ]] && opt_specs+="${p_opts} "

        _CONF_PKG_NAME["$conf_file"]="$p_name"
        _CONF_PKG_BIN["$conf_file"]="$p_bin"
        _CONF_PKG_DESC["$conf_file"]="$p_desc"
        _CONF_PKG_SCOPE["$conf_file"]="$p_scope"
        inst_specs="${inst_specs#"${inst_specs%%[![:space:]]*}"}"; inst_specs="${inst_specs%"${inst_specs##*[![:space:]]}"}"
        opt_specs="${opt_specs#"${opt_specs%%[![:space:]]*}"}"; opt_specs="${opt_specs%"${opt_specs##*[![:space:]]}"}"
        _CONF_PKG_INSTALL["$conf_file"]="$inst_specs"
        _CONF_PKG_OPTS["$conf_file"]="$opt_specs"

        if [[ "${_CONF_BASHRC_DIS["$pkg"]:-${_CONF_BASHRC_DIS["$target_key"]:-0}}" -ne 1 ]]; then
            _CONF_BASHRC["$conf_file"]="${_CONF_BASHRC_BUF["$pkg"]:-${_CONF_BASHRC_BUF["$target_key"]:-}}"
        else
            _CONF_BASHRC["$conf_file"]=""
        fi

        if [[ "${_CONF_TMPL_DIS["$pkg"]:-${_CONF_TMPL_DIS["$target_key"]:-0}}" -ne 1 ]]; then
            _CONF_TEMPLATES["$conf_file"]="${_CONF_TMPL_BUF["$pkg"]:-${_CONF_TMPL_BUF["$target_key"]:-}}"
        else
            _CONF_TEMPLATES["$conf_file"]=""
        fi

        _CONF_PARSED["$conf_file"]=1
    done
}

# Discover and resolve configuration file. If multiple configurations exist, prompt user.
_select_config_file() {
    local sdir="${1:-$SCRIPT_DIR}"
    if [[ -n "${CONFIG_FILE:-}" && -f "$CONFIG_FILE" ]]; then
        return 0
    fi

    local available_configs=()
    local cfg
    for cfg in "$sdir"/*.conf; do
        [[ ! -f "$cfg" ]] && continue
        local bname
        bname="$(basename "$cfg")"
        [[ "$bname" == "example.conf" ]] && continue
        available_configs+=("$bname")
    done

    if [[ ${#available_configs[@]} -eq 0 ]]; then
        CONFIG_FILE="$sdir/default.conf"
    elif [[ ${#available_configs[@]} -eq 1 ]]; then
        CONFIG_FILE="$sdir/${available_configs[0]}"
    else
        # Multiple configurations found
        if [[ "${NON_INTERACTIVE:-false}" == false ]]; then
            local choice
            choice="$(_ui_select "Multiple configuration files found. Select profile:" "${available_configs[@]}")"
            CONFIG_FILE="$sdir/${choice}"
        else
            if [[ -f "$sdir/default.conf" ]]; then
                CONFIG_FILE="$sdir/default.conf"
            else
                CONFIG_FILE="$sdir/${available_configs[0]}"
            fi
        fi
    fi
}

_preload_all_manifests() {
    local pdir="${1:-$PACKAGES_DIR}"
    [[ "$_CONF_CASCADE_DONE" -eq 1 ]] && return 0
    _CONF_CASCADE_DONE=1

    _select_config_file
    _preload_groups_conf

    _CONF_PKG_KEYS=()
    _CONF_PKG_DISABLED=()
    _CONF_PKG_DECLINED=()
    _CONF_BASHRC_BUF=()
    _CONF_BASHRC_DIS=()
    _CONF_TMPL_BUF=()
    _CONF_TMPL_DIS=()

    # Layer 1: default.conf
    local layer1="$SCRIPT_DIR/default.conf"
    if [[ -f "$layer1" ]]; then
        _parse_single_conf_file "$layer1" "global"
    fi

    # Layer 2: packages/*/*.conf
    if [[ -d "$pdir" ]]; then
        local conf_file
        for conf_file in "$pdir"/*/*.conf; do
            if [[ -f "$conf_file" ]]; then
                local pkg_default
                pkg_default="${conf_file#"$pdir/"}"
                pkg_default="${pkg_default%.conf}"
                _parse_single_conf_file "$conf_file" "$pkg_default"
            fi
        done
    fi

    # Layer 3: $CONFIG_FILE (selected or custom user config)
    if [[ -n "${CONFIG_FILE:-}" && -f "${CONFIG_FILE:-}" && "$CONFIG_FILE" != "$SCRIPT_DIR/default.conf" ]]; then
        _parse_single_conf_file "$CONFIG_FILE" "global"
    fi

    if [[ -n "${_CONF_PKG_KEYS["global:INSTALL_GROUPS"]:-}" ]]; then
        local raw_ig="${_CONF_PKG_KEYS["global:INSTALL_GROUPS"]}"
        raw_ig="${raw_ig//[()]/}"
        raw_ig="${raw_ig//,/ }"
        INSTALL_GROUPS=()
        local g
        for g in $raw_ig; do
            [[ -n "$g" ]] && INSTALL_GROUPS+=("$g")
        done
    fi

    _finalize_conf_caches "$pdir"
}

_preload_manifest_file() {
    local mfile="$1"
    local default_name="${2:-}"
    if [[ -z "$default_name" ]]; then
        if [[ "$mfile" == "$PACKAGES_DIR"/*/*.conf ]]; then
            default_name="${mfile#"$PACKAGES_DIR/"}"
            default_name="${default_name%.conf}"
        else
            default_name="$(basename "$mfile" .conf)"
        fi
    fi

    if [[ "$_CONF_CASCADE_DONE" -eq 0 ]]; then
        _preload_all_manifests "$PACKAGES_DIR"
    fi

    if [[ -z "${_CONF_PARSED["$mfile"]:-}" ]]; then
        _parse_single_conf_file "$mfile" "$default_name"
        _finalize_conf_caches "$PACKAGES_DIR"
    fi
}

_parse_manifest_file() {
    local mfile="$1"
    local default_name="${2:-}"
    if [[ -z "$default_name" ]]; then
        if [[ "$mfile" == "$PACKAGES_DIR"/*/*.conf ]]; then
            default_name="${mfile#"$PACKAGES_DIR/"}"
            default_name="${default_name%.conf}"
        else
            default_name="$(basename "$mfile" .conf)"
        fi
    fi

    _preload_manifest_file "$mfile" "$default_name"

    pkg_name="${_CONF_PKG_NAME["$mfile"]:-$default_name}"
    pkg_bin="${_CONF_PKG_BIN["$mfile"]:-}"
    pkg_desc="${_CONF_PKG_DESC["$mfile"]:-}"
    pkg_scope="${_CONF_PKG_SCOPE["$mfile"]:-system}"
    pkg_install="${_CONF_PKG_INSTALL["$mfile"]:-}"
    pkg_opts="${_CONF_PKG_OPTS["$mfile"]:-}"
}

_package_is_active() {
    local mfile="$1"
    local default_pkg
    if [[ "$mfile" == "$PACKAGES_DIR"/*/*.conf ]]; then
        default_pkg="${mfile#"$PACKAGES_DIR/"}"
        default_pkg="${default_pkg%.conf}"
    else
        default_pkg="$(basename "$mfile" .conf)"
    fi

    _parse_manifest_file "$mfile" "$default_pkg"
    local rest="${pkg_install}${pkg_install:+ }${pkg_opts}"

    [[ "${_CONF_PKG_DECLINED["$default_pkg"]:-0}" -eq 1 || "${_CONF_PKG_DECLINED["$pkg_name"]:-0}" -eq 1 ]] && return 1
    [[ "$(_get_opt disabled "$rest")" == true ]] && return 1
    _eval_cond "" "$rest" || return 1

    local needs_spec="$(_get_opt needs "$rest")"
    if [[ -n "$needs_spec" ]]; then
        local need_item
        local saved_ifs="$IFS"
        IFS=','
        for need_item in $needs_spec; do
            need_item="$(_trim "$need_item")"
            [[ -z "$need_item" ]] && continue
            if [[ "${_CONF_PKG_DISABLED["$need_item"]:-0}" -eq 1 || "${_CONF_PKG_DECLINED["$need_item"]:-0}" -eq 1 ]]; then
                IFS="$saved_ifs"
                return 1
            fi
            local dep_conf
            dep_conf="$(_find_pkg_manifest "$need_item" 2>/dev/null)" || dep_conf=""
            if [[ -n "$dep_conf" && -n "${_CONF_PKG_OPTS["$dep_conf"]:-}" ]] && ! _eval_cond "" "${_CONF_PKG_OPTS["$dep_conf"]}"; then
                IFS="$saved_ifs"
                return 1
            fi
        done
        IFS="$saved_ifs"
    fi
    return 0
}


_get_opt() {
    local key="$1" opts="$2"
    if [[ "$opts" =~ (^|[[:space:]])"$key":\"([^\"]+)\" ]]; then
        printf '%s' "${BASH_REMATCH[2]}"
    elif [[ "$opts" =~ (^|[[:space:]])"$key":\'([^\']+)\' ]]; then
        printf '%s' "${BASH_REMATCH[2]}"
    elif [[ "$opts" =~ (^|[[:space:]])"$key":([^[:space:]]+) ]]; then
        printf '%s' "${BASH_REMATCH[2]}"
    fi
}


_prompt_confirm() {
    local msg="$1" default_yes="${2:-false}"
    if [[ "${NON_INTERACTIVE:-false}" == true ]]; then
        [[ "$default_yes" == true ]] && return 0 || return 1
    fi
    local answer="" prompt_hint="" ind="${PROMPT_INDENT:-  }"
    if [[ "$default_yes" == true ]]; then
        prompt_hint="${CLR_MUTED}(${CLR_SUCCESS}${BOLD}Y${RESET}${CLR_MUTED}/n)${RESET}"
    else
        prompt_hint="${CLR_MUTED}(y/${CLR_WARN}${BOLD}N${RESET}${CLR_MUTED})${RESET}"
    fi
    _ui_bell
    printf '%s%s %s %s ' "$ind" "${CLR_PRIMARY}${SYM_Q}${RESET}" "${BOLD}${msg}${RESET}" "$prompt_hint" >&2
    if [[ ! -t 0 ]]; then
        read -r answer 2>/dev/null || true
    elif [[ -c /dev/tty ]]; then
        read -r answer < /dev/tty 2>/dev/null || read -r answer 2>/dev/null || true
    else
        read -r answer 2>/dev/null || true
    fi
    if [[ "$default_yes" == true ]]; then
        case "$answer" in
            [nN]|[nN][oO]) return 1 ;;
            *) return 0 ;;
        esac
    else
        case "$answer" in
            [yY]|[yY][eE][sS]) return 0 ;;
            *) return 1 ;;
        esac
    fi
}

# Return distro-specific package name, or the default name if none specified.
_resolve_pkg() {
    local default="$1" opts="$2" pm="$3"
    local key="$pm"
    [[ "$pm" == apt || "$pm" == apt-get ]] && key="apt"
    local override
    override="$(_get_opt "$key" "$opts")"
    printf '%s' "${override:-$default}"
}



# ── Module: src/installer.sh ──
# =============================================================================
#  INSTALLER ENGINE (Package Managers & Batch Queue)
# =============================================================================

_is_file_locked() {
    local f="$1"
    [[ ! -f "$f" ]] && return 1
    if command -v fuser >/dev/null 2>&1; then
        if fuser "$f" >/dev/null 2>&1 || { sudo -n true 2>/dev/null && sudo fuser "$f" >/dev/null 2>&1; }; then
            return 0
        fi
    elif command -v lsof >/dev/null 2>&1; then
        if lsof "$f" >/dev/null 2>&1 || { sudo -n true 2>/dev/null && sudo lsof "$f" >/dev/null 2>&1; }; then
            return 0
        fi
    elif command -v flock >/dev/null 2>&1; then
        flock -n "$f" -c true >/dev/null 2>&1 || return 0
    fi
    return 1
}

_wait_for_pm_lock() {
    local pm="${1:-${_PM:-}}"
    local max_wait="${2:-30}"
    local waited=0
    [[ "$DRY_RUN" == true || -z "$pm" || "$pm" == "unknown" ]] && return 0
    case "$pm" in
        apt|apt-get)
            local lock_files=(
                "/var/lib/dpkg/lock-frontend"
                "/var/lib/dpkg/lock"
                "/var/lib/apt/lists/lock"
                "/var/cache/apt/archives/lock"
            )
            while [[ $waited -lt $max_wait ]]; do
                local locked=false lf
                for lf in "${lock_files[@]}"; do
                    if _is_file_locked "$lf"; then
                        locked=true
                        break
                    fi
                done
                if [[ "$locked" == false ]]; then
                    return 0
                fi
                if [[ $waited -eq 0 ]]; then
                    log_warn "Waiting for package manager lock to release (${pm})..."
                fi
                sleep 2
                waited=$(( waited + 2 ))
            done
            log_warn "Package manager lock still held after ${max_wait}s. Proceeding anyway."
            ;;
        pacman)
            local db_lock="/var/lib/pacman/db.lck"
            while [[ $waited -lt $max_wait && -f "$db_lock" ]]; do
                if [[ $waited -eq 0 ]]; then
                    log_warn "Waiting for pacman lock ($db_lock) to release..."
                fi
                sleep 2
                waited=$(( waited + 2 ))
            done
            ;;
    esac
    return 0
}

_run_pm() {
    _wait_for_pm_lock "${_PM:-}"
    if [[ "$VERBOSE" == true ]]; then
        "$@"
    else
        _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Package manager" "$@"
    fi
}

# Wrapper: eval a script-method install command with retry and timeout.
_run_script() {
    local raw_cmd="$1"
    local label="${2:-Script install}"
    local timeout_val="${3:-}"
    [[ -z "$timeout_val" || ! "$timeout_val" =~ ^[0-9]+$ ]] && timeout_val="${INSTALL_TIMEOUT:-300}"
    local SPINNER_INDENT="${SPINNER_INDENT:-      }"
    if [[ "$VERIFY_SCRIPTS" == true || "${REVIEW_INSTALL_SCRIPTS:-false}" == true ]]; then
        log_info "Script target: $label"
        log_info "Command: $raw_cmd"
        if [[ "$NON_INTERACTIVE" != true ]]; then
            _ui_bell
            local _confirm=""
            read -r -p "Run this installation script? [y/N] " _confirm < /dev/tty || _confirm="n"
            if [[ "$_confirm" != [yY]* ]]; then
                log_warn "Skipped $label script."
                return 0
            fi
        fi
    fi
    local runner=()
    command -v timeout >/dev/null 2>&1 && runner=(timeout "${timeout_val}")
    _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "$label" "${runner[@]}" bash -c "set -o pipefail; $raw_cmd"
}



# ---------------------------------------------------------------------------
# Package installation
# Reads packages.conf; installs missing packages in batch per group.
# ---------------------------------------------------------------------------

# Update package manager index and upgrade installed packages.
_upgrade_system() {
    [[ "${SKIP_UPGRADE:-false}" == true ]] && { log_info "Skipping package upgrade (--skip-upgrade)."; return 0; }
    _PM="${_PM:-$(_detect_pm)}"
    [[ "$_PM" == unknown ]] && return 0

    if [[ "$DRY_RUN" == true ]]; then
        log_action "Would update, upgrade, and clean packages via ${_PM}"
        return 0
    fi

    _wait_for_pm_lock "$_PM"

    case "$_PM" in
        apt|apt-get)
            _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Updating package index (${_PM})" _sudo apt update -qq || true
            _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Upgrading packages (${_PM})" _sudo apt upgrade -y -qq
            _run_with_spinner "Removing unused packages (${_PM})" _sudo apt autoremove -y -qq || true
            ;;
        dnf)
            _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Upgrading packages (${_PM})" _sudo dnf upgrade -y
            _run_with_spinner "Removing unused packages (${_PM})" _sudo dnf autoremove -y || true
            ;;
        pacman)
            _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Updating package index (${_PM})" _sudo pacman -Sy --noconfirm || true
            _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Upgrading packages (${_PM})" _sudo pacman -Su --noconfirm
            ;;
        apk)
            _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Updating package index (${_PM})" _sudo apk update || true
            _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Upgrading packages (${_PM})" _sudo apk upgrade --no-cache
            ;;
        zypper)
            _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Updating package index (${_PM})" _sudo zypper ref || true
            _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Upgrading packages (${_PM})" _sudo zypper dup -y
            ;;
    esac
}

# Flush the accumulated native package queue and install in one PM call.
_flush_native_q() {
    [[ ${#_NATIVE_Q[@]} -eq 0 ]] && return
    local SPINNER_INDENT="    "

    if [[ "$_PM" == unknown ]]; then
        printf '    %s %s\n' "${CLR_ERROR}${BOLD}${SYM_FAIL}${RESET}" "No package manager found. Cannot install: ${_NATIVE_Q[*]}" >&2
        _NATIVE_Q=(); return
    fi

    local -a update_cmd=() install_cmd=()
    case "$_PM" in
        apt|apt-get)
            update_cmd=(_sudo apt update -qq)
            install_cmd=(_sudo apt install -y -qq) ;;
        dnf)     install_cmd=(_sudo dnf install -y) ;;
        pacman)  install_cmd=(_sudo pacman -Sy --noconfirm) ;;
        zypper)  install_cmd=(_sudo zypper install -y) ;;
        apk)     install_cmd=(_sudo apk add --no-cache) ;;
    esac

    if [[ "$DRY_RUN" == true ]]; then
        printf '    %s %s\n' "${CLR_WARN}${BOLD}[DRY-RUN]${RESET}" "Would install (${_PM}): ${_NATIVE_Q[*]}" >&2
    else
        _wait_for_pm_lock "$_PM"
        if [[ ${#update_cmd[@]} -gt 0 ]]; then
            "${update_cmd[@]}" >/dev/null 2>&1 || true
        fi
        local q_label="Installing ${#_NATIVE_Q[@]} packages via ${_PM}"
        [[ ${#_NATIVE_Q[@]} -eq 1 ]] && q_label="Installing '${_NATIVE_Q[0]}' via ${_PM}"

        if ! _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "$q_label" "${install_cmd[@]}" "${_NATIVE_Q[@]}"; then
            printf '    %s %s\n' "${CLR_WARN}${SYM_WARN}${RESET}" "Batch install (${_PM}) failed. Retrying packages individually..." >&2
            local p
            for p in "${_NATIVE_Q[@]}"; do
                _wait_for_pm_lock "$_PM"
                _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "Installing '${p}' via ${_PM}" "${install_cmd[@]}" "$p" || {
                    printf '    %s %s\n' "${CLR_WARN}${SYM_WARN}${RESET}" "Failed to install '${p}' via ${_PM}." >&2
                    _FAILED_PACKAGES+=("$p")
                    _FAILURE_REASONS["$p"]="${_LAST_CMD_ERROR:-Package install failed via ${_PM}}"
                }
            done
        fi
    fi
    _NATIVE_Q=()
}

# Flush native and script installation queues for the current package group.
_flush_group_installs() {
    _flush_native_q

    local i
    for i in "${!_FALLBACK_NAMES[@]}"; do
        if ! _check_bins "${_FALLBACK_BINS[$i]}"; then
            printf '    %s %s\n' "${CLR_WARN}${SYM_WARN}${RESET}" "'${_FALLBACK_NAMES[$i]}' not found after package install. Using script fallback." >&2
            _SCRIPT_NAMES+=("${_FALLBACK_NAMES[$i]}")
            _SCRIPT_CMDS+=("${_FALLBACK_CMDS[$i]}")
        fi
    done
    _FALLBACK_NAMES=(); _FALLBACK_BINS=(); _FALLBACK_CMDS=()

    for i in "${!_SCRIPT_NAMES[@]}"; do
        if [[ "$DRY_RUN" == true ]]; then
            log_action "Would install via script: ${_SCRIPT_NAMES[$i]}"
        else
            _run_script "${_SCRIPT_CMDS[$i]}" "Installing '${_SCRIPT_NAMES[$i]}' via script" || log_warn "Failed to install '${_SCRIPT_NAMES[$i]}' via script."
        fi
    done
    _SCRIPT_NAMES=(); _SCRIPT_CMDS=()

    for i in "${!_POST_CMDS[@]}"; do
        if [[ "$DRY_RUN" == true ]]; then
            log_action "Would run post-install hook: ${_POST_CMDS[$i]}"
        else
            bash -c "${_POST_CMDS[$i]}" >/dev/null 2>&1 || log_warn "Post-install hook failed for '${_POST_NAMES[$i]:-script}'."
        fi
    done
    _POST_CMDS=(); _POST_NAMES=()
}

_find_pkg_manifest() {
    local target="$1"
    local pdir="${PACKAGES_DIR:-$SCRIPT_DIR/packages}"
    local cand
    for cand in "$pdir"/*/"${target}.conf"; do
        if [[ -f "$cand" ]]; then
            printf '%s' "$cand"
            return 0
        fi
    done
    return 1
}

_resolve_missing_dependency() {
    local parent_pkg="$1"
    local dep="$2"

    if _check_bins_scoped "$dep" "any"; then
        return 0
    fi

    local dep_conf
    dep_conf="$(_find_pkg_manifest "$dep")" || dep_conf=""

    if [[ -z "$dep_conf" ]]; then
        log_warn "Skipping '${parent_pkg}': required external dependency '${dep}' is not installed."
        _CONF_PKG_DECLINED["$parent_pkg"]=1
        return 1
    fi

    if [[ -n "${_CONF_PKG_OPTS["$dep_conf"]:-}" ]] && ! _eval_cond "" "${_CONF_PKG_OPTS["$dep_conf"]}"; then
        log_warn "Skipping '${parent_pkg}': required dependency '${dep}' is unavailable in current environment."
        _CONF_PKG_DECLINED["$parent_pkg"]=1
        return 1
    fi

    if [[ "${NON_INTERACTIVE:-false}" == true ]]; then
        log_warn "Skipping '${parent_pkg}': required dependency '${dep}' is not installed."
        _CONF_PKG_DECLINED["$parent_pkg"]=1
        return 1
    fi

    _ui_bell
    if _prompt_confirm "'${parent_pkg}' requires '${dep}' (skipped). Install '${dep}' now?" true; then
        log_info "Installing missing prerequisite '${dep}' for '${parent_pkg}'..."
        _CONF_PKG_DECLINED["$dep"]=0
        _CONF_PKG_DISABLED["$dep"]=0
        _install_single_package "$dep_conf" "$dep"
        if _check_bins_scoped "$dep" "any"; then
            return 0
        else
            log_warn "Prerequisite '${dep}' installation failed. Skipping '${parent_pkg}'."
            _CONF_PKG_DECLINED["$parent_pkg"]=1
            return 1
        fi
    else
        log_warn "Skipping '${parent_pkg}' because prerequisite '${dep}' was declined."
        _CONF_PKG_DECLINED["$parent_pkg"]=1
        return 1
    fi
}

_install_single_package() {
    local conf_file="$1"
    local cpkg="$2"
    [[ ! -f "$conf_file" ]] && return 0

    _parse_manifest_file "$conf_file" "$cpkg"

    local pkg_id="$pkg_name"
    local bin="${pkg_bin:-$pkg_id}"
    local scope="$pkg_scope"
    local rest="${pkg_install}${pkg_install:+ }${pkg_opts}"

    local pm_key="${_PM:-}"
    [[ "$pm_key" == "apt-get" ]] && pm_key="apt"
    local group="$(basename "$(dirname "$conf_file")")"
    local target_key="${group}/${pkg_id}"
    local pm_cmd="${_CONF_PKG_KEYS["${target_key}:${pm_key}.cmd"]:-${_CONF_PKG_KEYS["${pkg_id}:${pm_key}.cmd"]:-${_CONF_PKG_KEYS["${cpkg}:${pm_key}.cmd"]:-}}}"
    [[ -z "$pm_cmd" ]] && pm_cmd="$(_get_opt "${pm_key}.cmd" "$rest")"
    local scmd="${pm_cmd:-${_CONF_PKG_KEYS["${target_key}:cmd"]:-${_CONF_PKG_KEYS["${pkg_id}:cmd"]:-${_CONF_PKG_KEYS["${cpkg}:cmd"]:-}}}}"
    [[ -z "$scmd" ]] && scmd="${pm_cmd:-$(_get_opt cmd "$rest")}"
    local mise_spec="$(_get_opt mise "$rest")"
    local uv_spec="$(_get_opt uv "$rest")"
    local cargo_spec="$(_get_opt cargo "$rest")"
    local go_spec="$(_get_opt go "$rest")"
    local bun_spec="$(_get_opt bun "$rest")"
    local npm_spec="$(_get_opt npm "$rest")"
    local flatpak_spec="$(_get_opt flatpak "$rest")"
    local brew_spec="$(_get_opt brew "$rest")"

    local provider="script"
    if [[ -z "$scmd" ]]; then
        if [[ -n "$mise_spec" ]]; then
            provider="mise"
            [[ "$mise_spec" != *":"* && "$mise_spec" == *"/"* ]] && mise_spec="github:${mise_spec}"
            scmd="~/.local/bin/mise use -g ${mise_spec}"
        elif [[ -n "$uv_spec" ]]; then
            provider="uv"
            scmd="\"${HOME}/.local/bin/uv\" tool install ${uv_spec} 2>/dev/null || uv tool install ${uv_spec}"
        elif [[ -n "$cargo_spec" ]]; then
            provider="cargo"
            scmd="if command -v cargo-binstall >/dev/null 2>&1; then cargo binstall --no-confirm ${cargo_spec}; else cargo install ${cargo_spec}; fi"
        elif [[ -n "$go_spec" ]]; then
            provider="go"
            [[ "$go_spec" != *"@"* ]] && go_spec="${go_spec}@latest"
            scmd="go install ${go_spec}"
        elif [[ -n "$bun_spec" ]]; then
            provider="bun"
            scmd="bun add -g ${bun_spec}"
        elif [[ -n "$npm_spec" ]]; then
            provider="npm"
            scmd="npm install -g ${npm_spec}"
        elif [[ -n "$flatpak_spec" ]]; then
            provider="flatpak"
            scmd="flatpak install --user -y ${flatpak_spec}"
        elif [[ -n "$brew_spec" ]]; then
            provider="brew"
            scmd="brew install ${brew_spec}"
        fi
    fi

    # Determine native vs script
    local is_native=false
    local resolved=""
    case "$scope" in
        system|native)
            if [[ -z "$pm_cmd" ]]; then
                local pm_pkg="$(_get_opt "$pm_key" "$rest")"
                if [[ -n "$pm_pkg" || -z "$scmd" ]]; then
                    resolved="$(_resolve_pkg "$pkg_id" "$rest" "$_PM")"
                    if [[ "$resolved" != "none" && "$resolved" != ":none" && "$resolved" != "skip" && "$resolved" != "!"* ]]; then
                        is_native=true
                    fi
                fi
            fi
            ;;
    esac

    # Check needs dependency prerequisites with forgiving interactive fallback
    local needs_spec="$(_get_opt needs "$rest")"
    if [[ -n "$needs_spec" ]]; then
        local need_item
        local saved_ifs="$IFS"
        IFS=','
        for need_item in $needs_spec; do
            need_item="$(_trim "$need_item")"
            [[ -z "$need_item" ]] && continue
            if ! _resolve_missing_dependency "$pkg_id" "$need_item"; then
                IFS="$saved_ifs"
                return 0
            fi
        done
        IFS="$saved_ifs"
    fi

    # 1. Install package if binary is not present in declared scope
    if ! _check_bins_scoped "$bin" "$scope"; then
        # Run prep hook if present
        local prep_cmd="${_CONF_PKG_KEYS["${target_key}:${pm_key}.prep"]:-${_CONF_PKG_KEYS["${pkg_id}:${pm_key}.prep"]:-${_CONF_PKG_KEYS["${cpkg}:${pm_key}.prep"]:-${_CONF_PKG_KEYS["${target_key}:prep"]:-${_CONF_PKG_KEYS["${pkg_id}:prep"]:-${_CONF_PKG_KEYS["${cpkg}:prep"]:-}}}}}}"
        [[ -z "$prep_cmd" ]] && prep_cmd="$(_get_opt "${pm_key}.prep" "$rest")"
        [[ -z "$prep_cmd" ]] && prep_cmd="$(_get_opt prep "$rest")"
        if [[ -n "$prep_cmd" ]]; then
            if [[ "$DRY_RUN" == true ]]; then
                log_action "    prep: $prep_cmd"
            else
                SPINNER_INDENT="      " _run_script "$prep_cmd" "prep: $prep_cmd" || log_warn "Prep hook failed for '$pkg_id'."
            fi
        fi

        local install_success=false
        if [[ "$is_native" == true ]]; then
            local -a install_cmd=()
            case "$_PM" in
                apt|apt-get) install_cmd=(_sudo apt install -y -qq) ;;
                dnf)         install_cmd=(_sudo dnf install -y) ;;
                pacman)      install_cmd=(_sudo pacman -Sy --noconfirm) ;;
                zypper)      install_cmd=(_sudo zypper install -y) ;;
                apk)         install_cmd=(_sudo apk add --no-cache) ;;
            esac
            if [[ "$DRY_RUN" == true ]]; then
                log_success "$pkg_id (${_PM})"
                install_success=true
            else
                if [[ ${#install_cmd[@]} -gt 0 ]]; then
                    _wait_for_pm_lock "$_PM"
                    if SPINNER_INDENT="  " _run_retry "$MAX_RETRIES" "$RETRY_DELAY" "${pkg_id} (${_PM})" "${install_cmd[@]}" "$resolved"; then
                        install_success=true
                    else
                        log_warn "Failed to install '${pkg_id}' via ${_PM}."
                    fi
                fi
            fi
        fi

        # Script or fallback installation
        if [[ "$install_success" == false && -n "$scmd" ]]; then
            if [[ "$DRY_RUN" == true ]]; then
                log_success "$pkg_id (${provider})"
            else
                local pkg_timeout="$(_get_pkg_prop "$pkg_id" "$target_key" "" "timeout")"
                [[ -z "$pkg_timeout" ]] && pkg_timeout="$(_get_pkg_prop "$cpkg" "$target_key" "" "timeout")"
                [[ -z "$pkg_timeout" ]] && pkg_timeout="$(_get_opt timeout "$rest")"
                if SPINNER_INDENT="  " _run_script "$scmd" "${pkg_id} (${provider})" "${pkg_timeout:-$INSTALL_TIMEOUT}"; then
                    install_success=true
                else
                    log_warn "Failed to install '${pkg_id}' via ${provider}."
                fi
            fi
        fi

        local proceed_post=true
        if [[ "$install_success" == false ]]; then
            _FAILED_PACKAGES+=("$pkg_id")
            _FAILURE_REASONS["$pkg_id"]="${_LAST_CMD_ERROR:-Installation failed}"
            _CONF_PKG_DECLINED["$pkg_id"]=1

            local has_post_actions=false
            local post_cmd="${_CONF_PKG_KEYS["${target_key}:${pm_key}.post"]:-${_CONF_PKG_KEYS["${pkg_id}:${pm_key}.post"]:-${_CONF_PKG_KEYS["${cpkg}:${pm_key}.post"]:-${_CONF_PKG_KEYS["${target_key}:post"]:-${_CONF_PKG_KEYS["${pkg_id}:post"]:-${_CONF_PKG_KEYS["${cpkg}:post"]:-}}}}}}"
            [[ -z "$post_cmd" ]] && post_cmd="$(_get_opt "${pm_key}.post" "$rest")"
            [[ -z "$post_cmd" ]] && post_cmd="$(_get_opt post "$rest")"
            local tmpl_check
            tmpl_check="$(_extract_templates "$conf_file")"
            if [[ -n "$post_cmd" || -n "$tmpl_check" ]]; then
                has_post_actions=true
            fi

            if [[ "$has_post_actions" == true ]]; then
                if [[ "$DRY_RUN" == true ]]; then
                    proceed_post=true
                elif [[ "${NON_INTERACTIVE:-false}" == true ]]; then
                    proceed_post=false
                    log_info "Skipping post-installation and configuration templates for failed package '$pkg_id'."
                else
                    _ui_bell
                    if _prompt_confirm "Installation of '${pkg_id}' failed. Proceed with post-installation hooks and configuration templates?" false; then
                        proceed_post=true
                    else
                        proceed_post=false
                        log_info "Skipped post-installation and configuration templates for '$pkg_id'."
                    fi
                fi
            else
                proceed_post=false
            fi
        fi

        if [[ "$proceed_post" == true ]]; then
            # Run post hook if present (before verification so symlinks/wrappers exist)
            local post_cmd="${_CONF_PKG_KEYS["${target_key}:${pm_key}.post"]:-${_CONF_PKG_KEYS["${pkg_id}:${pm_key}.post"]:-${_CONF_PKG_KEYS["${cpkg}:${pm_key}.post"]:-${_CONF_PKG_KEYS["${target_key}:post"]:-${_CONF_PKG_KEYS["${pkg_id}:post"]:-${_CONF_PKG_KEYS["${cpkg}:post"]:-}}}}}}"
            [[ -z "$post_cmd" ]] && post_cmd="$(_get_opt "${pm_key}.post" "$rest")"
            [[ -z "$post_cmd" ]] && post_cmd="$(_get_opt post "$rest")"
            if [[ -n "$post_cmd" ]]; then
                if [[ "$DRY_RUN" == true ]]; then
                    log_action "    post: $post_cmd"
                else
                    SPINNER_INDENT="      " _run_script "$post_cmd" "post: $post_cmd" || log_warn "Post hook failed for '$pkg_id'."
                fi
            fi

            # Deploy templates and configs for this package
            LOG_INDENT="      " SPINNER_INDENT="      " deploy_package_templates "$conf_file"
        fi

        # Post-install scope monitoring & verification
        if [[ "$DRY_RUN" != true && "$install_success" == true ]]; then
            hash -r 2>/dev/null || true
            if ! _check_bins_scoped "$bin" "$scope" && [[ "$scope" != "script" ]]; then
                log_warn "'${pkg_id}' binary not found in ${scope} PATH after installation."
                _FAILED_PACKAGES+=("$pkg_id")
                _FAILURE_REASONS["$pkg_id"]="${_LAST_CMD_ERROR:-Binary not found in ${scope} PATH}"
                _CONF_PKG_DECLINED["$pkg_id"]=1
            fi
        fi
    else
        log_success "$pkg_id"
        # Deploy templates and configs for this package
        LOG_INDENT="      " SPINNER_INDENT="      " deploy_package_templates "$conf_file"
    fi
}

install_packages() {
    local pdir="${1:-$PACKAGES_DIR}"
    [[ ! -d "$pdir" ]] && { log_warn "Packages directory not found. Skipping package installation."; return 0; }
    _preload_all_manifests "$pdir"
    _PM="${_PM:-$(_detect_pm)}"

    # 1. Group Multi-Selector
    local grp_ids=() grp_labels=() grp_descs=() grp_states=() grp_locks=()
    local g
    while IFS= read -r g; do
        [[ -z "$g" ]] && continue
        local is_opt
        is_opt="$(_get_group_meta "$g" "optional")"
        local desc
        desc="$(_get_group_meta "$g" "description")"

        grp_ids+=("$g")
        grp_labels+=("$g")
        grp_descs+=("$desc")

        if [[ "$is_opt" == "false" || "$g" == "core" ]]; then
            grp_locks+=("required")
            grp_states+=(1)
        elif [[ ${#INSTALL_GROUPS[@]} -gt 0 ]]; then
            if _group_selected "$g"; then
                grp_locks+=("optional")
                grp_states+=(1)
            else
                grp_locks+=("optional")
                grp_states+=(0)
            fi
        else
            grp_locks+=("optional")
            grp_states+=(0)
        fi
    done < <(_get_groups)

    local selected_groups_raw
    selected_groups_raw="$(_ui_multiselect "Select package groups" grp_ids grp_labels grp_descs grp_states grp_locks)"
    local -a active_groups=()
    read -ra active_groups <<< "$selected_groups_raw"
    INSTALL_GROUPS=("${active_groups[@]}")

    # Mark unselected groups as declined
    local ag
    for ag in "${grp_ids[@]}"; do
        local g_active=0
        for g in "${active_groups[@]}"; do
            [[ "$g" == "$ag" ]] && { g_active=1; break; }
        done
        if [[ $g_active -eq 0 ]]; then
            local unsel_pkg
            while IFS= read -r unsel_pkg; do
                [[ -n "$unsel_pkg" ]] && _CONF_PKG_DECLINED["$unsel_pkg"]=1
            done < <(_get_group_packages "$ag")
        fi
    done

    # 2. Iterate each selected group: Package Multi-Selector & Package-by-Package Lifecycle
    local current_group
    for current_group in "${active_groups[@]}"; do
        [[ -z "$current_group" ]] && continue

        local pkg_ids=() pkg_labels=() pkg_descs=() pkg_states=() pkg_locks=()
        local pkg
        while IFS= read -r pkg; do
            [[ -z "$pkg" ]] && continue
            local conf_file="$pdir/$current_group/$pkg.conf"
            [[ ! -f "$conf_file" ]] && continue

            _parse_manifest_file "$conf_file" "$pkg"

            local pkg_id="$pkg_name"
            local bin="${pkg_bin:-$pkg_id}"
            local scope="$pkg_scope"
            local desc="$pkg_desc"
            local rest="${pkg_install}${pkg_install:+ }${pkg_opts}"

            pkg_ids+=("$pkg")
            pkg_labels+=("$pkg_id")
            pkg_descs+=("$desc")

            local needs_spec="$(_get_opt needs "$rest")"
            local needs_missing=""
            if [[ -n "$needs_spec" ]]; then
                local need_item
                local saved_ifs="$IFS"
                IFS=','
                for need_item in $needs_spec; do
                    need_item="$(_trim "$need_item")"
                    [[ -z "$need_item" ]] && continue
                    if [[ "${_CONF_PKG_DISABLED["$need_item"]:-0}" -eq 1 || "${_CONF_PKG_DECLINED["$need_item"]:-0}" -eq 1 ]]; then
                        needs_missing="$need_item"
                        break
                    elif ! _check_bins_scoped "$need_item" "any"; then
                        local has_active_manifest=false
                        local cand_file
                        for cand_file in "$PACKAGES_DIR"/*/"${need_item}.conf"; do
                            if [[ -f "$cand_file" ]]; then
                                if _package_is_active "$cand_file" 2>/dev/null; then
                                    has_active_manifest=true
                                fi
                                break
                            fi
                        done
                        if [[ "$has_active_manifest" == false ]]; then
                            needs_missing="$need_item"
                            break
                        fi
                    fi
                done
                IFS="$saved_ifs"
            fi

            if [[ "$(_get_opt disabled "$rest")" == true || "${_CONF_PKG_DISABLED["$pkg"]:-0}" -eq 1 ]]; then
                pkg_locks+=("disabled")
                pkg_states+=(0)
            elif ! _eval_cond "" "$rest"; then
                local cond_reason
                cond_reason="$(_get_failed_cond_reason "" "$rest")"
                pkg_locks+=("unsupported:${cond_reason:-unmet}")
                pkg_states+=(0)
            elif [[ -n "$needs_missing" ]]; then
                if _find_pkg_manifest "$needs_missing" >/dev/null 2>&1; then
                    pkg_locks+=("alt:needs ${needs_missing}")
                    pkg_states+=(0)
                else
                    pkg_locks+=("disabled:missing ${needs_missing}")
                    pkg_states+=(0)
                fi
            elif _check_bins_scoped "$bin" "$scope"; then
                pkg_locks+=("installed:${REPLY_PATH:-$REPLY}")
                pkg_states+=(1)
            else
                local alt_target="$(_get_opt alt "$rest")"
                local alt_installed=false
                if [[ -n "$alt_target" ]] && _check_bins_scoped "$alt_target" "$scope"; then
                    alt_installed=true
                fi
                local is_opt="$(_get_opt optional "$rest")"
                local is_rec="$(_get_opt recommended "$rest")"

                if [[ "$is_opt" != true && -z "$alt_target" ]]; then
                    pkg_locks+=("required")
                    pkg_states+=(1)
                elif [[ -n "$alt_target" ]]; then
                    if [[ "$alt_installed" == true ]]; then
                        pkg_locks+=("alt:${alt_target} installed")
                        pkg_states+=(0)
                    else
                        pkg_locks+=("alt:${alt_target}")
                        pkg_states+=(1)
                    fi
                elif [[ "$is_rec" == true ]]; then
                    pkg_locks+=("recommended")
                    pkg_states+=(1)
                else
                    pkg_locks+=("optional")
                    if [[ ${#OPTIONAL_PACKAGES[@]} -gt 0 ]]; then
                        local opt_match=0 op
                        for op in "${OPTIONAL_PACKAGES[@]}"; do
                            [[ "$op" == "$pkg" || "$op" == "$pkg_id" ]] && opt_match=1 && break
                        done
                        pkg_states+=($opt_match)
                    else
                        pkg_states+=(1)
                    fi
                fi
            fi
        done < <(_get_group_packages "$current_group")

        if [[ ${#pkg_ids[@]} -gt 0 ]]; then
            local chosen_pkgs_raw
            chosen_pkgs_raw="$(_ui_multiselect "Packages in [${current_group}]" pkg_ids pkg_labels pkg_descs pkg_states pkg_locks)"
            local -a chosen_pkgs=()
            read -ra chosen_pkgs <<< "$chosen_pkgs_raw"

            # Track declined packages in this group
            local pid
            for pid in "${pkg_ids[@]}"; do
                local is_chosen=0 c
                for c in "${chosen_pkgs[@]}"; do
                    [[ "$c" == "$pid" ]] && { is_chosen=1; break; }
                done
                if [[ $is_chosen -eq 0 ]]; then
                    _CONF_PKG_DECLINED["$pid"]=1
                fi
            done

            # Execute package-by-package lifecycle: install -> config/templates -> post hook -> next package
            local cpkg
            for cpkg in "${chosen_pkgs[@]}"; do
                [[ -z "$cpkg" ]] && continue
                local conf_file="$pdir/$current_group/$cpkg.conf"
                [[ ! -f "$conf_file" ]] && continue

                _install_single_package "$conf_file" "$cpkg"
            done
        fi
    done

    return 0
}

# ── Module: src/deploy.sh ──
# =============================================================================
#  DEPLOYMENT MODULES (Atomic Writes, Templates, Stow, Rollback)
# =============================================================================

# ---------------------------------------------------------------------------
# Atomic File Writer & Backup Manager
# ---------------------------------------------------------------------------
_write_file() {
    local target="$1" content="$2" flags="${3:-}"
    local dest="${target/#\~/$HOME}"

    # Ensure single trailing newline if missing while preserving template formatting
    if [[ -n "$content" && "$content" != *$'\n' ]]; then
        content+=$'\n'
    fi

    # System-scoped target path (e.g. /etc/sysctl.d/...) - direct root write bypassing stow
    if [[ "$dest" != "$HOME/"* && "$dest" != "$HOME" ]]; then
        if [[ "$flags" == *once* && "$FORCE" != true ]] && [[ -f "$dest" ]]; then
            log_info "Already exists, skipping: ${dest}"
            return
        fi
        if [[ -f "$dest" ]] && printf '%s' "$content" | cmp -s - "$dest"; then
            log_info "Up to date: ${dest}"
            return
        fi
        if [[ "$DRY_RUN" == true ]]; then
            log_action "Would write system file: ${dest}"
        else
            local tmp
            tmp="$(mktemp "${TMPDIR:-/tmp}/dotfiles_sys_XXXXXX")"
            printf '%s' "$content" > "$tmp"
            _sudo mkdir -p "$(dirname "$dest")"
            _sudo cp "$tmp" "$dest"
            _sudo chmod 644 "$dest"
            rm -f "$tmp"
            log_success "Wrote system file: ${dest}"
        fi
        return
    fi

    local rel="${dest#"$HOME/"}"
    local stow_src="$DOTFILES_DIR/$rel"

    # "once": create only if absent in dotfiles directory (bypassed if FORCE=true)
    if [[ "$flags" == *once* && "$FORCE" != true && -f "$stow_src" ]]; then
        log_info "Already exists, skipping: ${rel}"
    elif [[ -f "$stow_src" ]] && printf '%s' "$content" | cmp -s - "$stow_src"; then
        log_info "Up to date: ${rel}"
    else
        if [[ "$DRY_RUN" == true ]]; then
            log_action "Would write template: ${target}"
        else
            mkdir -p "$(dirname "$stow_src")"
            local tmp
            tmp="$(mktemp "${stow_src}.XXXXXX")"
            printf '%s' "$content" > "$tmp"
            chmod 644 "$tmp" 2>/dev/null || true
            mv "$tmp" "$stow_src"
            log_success "Wrote template: ${target}"
        fi
    fi

    # Back up and clear pre-existing regular file in $HOME before stow symlinks it
    if [[ -e "$dest" || -L "$dest" ]]; then
        local real_dest real_stow
        real_dest="$(readlink -f "$dest" 2>/dev/null || true)"
        real_stow="$(readlink -f "$stow_src" 2>/dev/null || true)"
        if [[ -n "$real_stow" && "$real_dest" != "$real_stow" ]]; then
            if [[ -f "$dest" && ! -L "$dest" ]]; then
                if [[ "$DRY_RUN" == true ]]; then
                    log_action "Would back up existing file: ${target}"
                else
                    _get_backup_dir
                    mkdir -p "$BACKUP_DIR/$(dirname "$rel")"
                    
                    local file_sha="" file_mode=""
                    if command -v sha256sum >/dev/null 2>&1; then
                        read -r file_sha _ < <(sha256sum "$dest" 2>/dev/null || true)
                    fi
                    if command -v stat >/dev/null 2>&1; then
                        file_mode="$(stat -c '%a' "$dest" 2>/dev/null || echo "644")"
                    fi

                    mv "$dest" "$BACKUP_DIR/$rel"
                    BACKUP_COUNT=$((BACKUP_COUNT + 1))

                    # Append to backup manifest
                    local manifest_file="$BACKUP_DIR/.backup_manifest.json"
                    local entry_json
                    entry_json="{\"rel\":\"${rel}\",\"dest\":\"${dest}\",\"sha256\":\"${file_sha}\",\"mode\":\"${file_mode}\",\"timestamp\":\"$(date -u +%Y-%m-%dT%H:%M:%SZ)\"}"
                    if [[ ! -f "$manifest_file" ]]; then
                        printf '[\n  %s\n]\n' "$entry_json" > "$manifest_file"
                    else
                        # Insert before the last line
                        sed -i '$d' "$manifest_file" 2>/dev/null || true
                        printf ',\n  %s\n]\n' "$entry_json" >> "$manifest_file"
                    fi

                    log_action "Backed up existing file: ${target}"
                fi
            elif [[ -L "$dest" ]]; then
                if [[ "$DRY_RUN" == true ]]; then
                    log_action "Would remove obsolete symlink: ${target}"
                else
                    rm -f "$dest"
                fi
            fi
        fi
    fi
}

# ---------------------------------------------------------------------------
# Rollback Engine: Restores timestamped backup snapshots
# ---------------------------------------------------------------------------
_rollback_latest_backup() {
    local target_snap="${1:-}"
    local bak_root="$HOME/.dotfiles.bak"
    if [[ ! -d "$bak_root" ]]; then
        log_error "No backup directory found at ${bak_root}."
        return 1
    fi

    local snapshots=()
    local sdir
    while IFS= read -r sdir; do
        [[ -n "$sdir" && -d "$sdir" ]] && snapshots+=("$sdir")
    done < <(find "$bak_root" -mindepth 1 -maxdepth 1 -type d | sort -r)

    if [[ ${#snapshots[@]} -eq 0 ]]; then
        log_error "No backup snapshots found in ${bak_root}."
        return 1
    fi

    local chosen_bak=""
    if [[ -n "$target_snap" ]]; then
        if [[ -d "$bak_root/$target_snap" ]]; then
            chosen_bak="$bak_root/$target_snap"
        elif [[ -d "$target_snap" ]]; then
            chosen_bak="$target_snap"
        else
            log_error "Specified snapshot '$target_snap' does not exist."
            return 1
        fi
    elif [[ ${#snapshots[@]} -eq 1 || "${NON_INTERACTIVE:-false}" == true || ! -t 0 ]]; then
        chosen_bak="${snapshots[0]}"
    else
        local snap_names=()
        local s
        for s in "${snapshots[@]}"; do
            snap_names+=("$(basename "$s")")
        done
        local sel
        sel="$(_ui_select "Select backup snapshot to restore:" "${snap_names[@]}")"
        chosen_bak="$bak_root/$sel"
    fi

    log_info "Rolling back from snapshot: $(basename "$chosen_bak")"
    local restored_count=0
    local bak_file
    while IFS= read -r -d '' bak_file; do
        local rel="${bak_file#"$chosen_bak/"}"
        [[ "$rel" == ".backup_manifest.json" ]] && continue
        local dest="$HOME/$rel"
        mkdir -p "$(dirname "$dest")"
        cp -a "$bak_file" "$dest"
        log_success "Restored: ~/${rel}"
        restored_count=$((restored_count + 1))
    done < <(find "$chosen_bak" -type f -print0)

    if [[ $restored_count -eq 0 ]]; then
        log_warn "Backup snapshot was empty."
        return 0
    fi
    log_success "Rollback complete. Restored ${restored_count} file(s) from $(basename "$chosen_bak")."
    return 0
}

# ---------------------------------------------------------------------------
# Template deployment
# ---------------------------------------------------------------------------
_extract_templates() {
    local file="$1"
    _preload_manifest_file "$file"
    printf '%s' "${_CONF_TEMPLATES["$file"]:-}"
}

deploy_package_templates() {
    local conf_file="$1"
    [[ ! -f "$conf_file" ]] && return 0
    local LOG_INDENT="${LOG_INDENT:-    }"
    local SPINNER_INDENT="${SPINNER_INDENT:-    }"
    _preload_manifest_file "$conf_file"

    local tmpl_all
    tmpl_all="$(_extract_templates "$conf_file")"
    [[ -z "$tmpl_all" ]] && return 0

    local rest="$tmpl_all"
    while [[ -n "$rest" ]]; do
        local template_content=""
        if [[ "$rest" == *"__TMPL_SEP__"* ]]; then
            template_content="${rest%%__TMPL_SEP__*}"
            rest="${rest#*__TMPL_SEP__}"
        else
            template_content="$rest"
            rest=""
        fi
        [[ -z "$template_content" ]] && continue

        local first_line tmpl_target="" tmpl_flags="" content=""
        first_line="${template_content%%$'\n'*}"
        if [[ "$first_line" =~ ^#[[:space:]]*target:[[:space:]]*([^[:space:]]+)([[:space:]]+flags:(.+))? ]]; then
            tmpl_target="${BASH_REMATCH[1]}"
            [[ -n "${BASH_REMATCH[3]:-}" ]] && tmpl_flags="${BASH_REMATCH[3]}"
            content="${template_content#*$'\n'}"
        else
            content="$template_content"
        fi

        local tmpl_cond=""
        if [[ "$tmpl_flags" =~ cond=([^[:space:]]+) || "$tmpl_flags" =~ cond:([^[:space:]]+) ]]; then
            tmpl_cond="${BASH_REMATCH[1]}"
        fi
        if [[ -n "$tmpl_cond" ]]; then
            if ! _eval_cond "$tmpl_cond"; then
                log_info "Skipping template (unmet condition $tmpl_cond): $tmpl_target"
                continue
            fi
        fi

        local pkg_name="${conf_file##*/}"; pkg_name="${pkg_name%.conf}"
        local var_name="TEMPLATE_OVERRIDE_${pkg_name^^}"
        var_name="${var_name//-/_}"
        local override_content="${!var_name:-}"
        [[ -n "$override_content" ]] && content="$override_content"

        if [[ -n "$tmpl_target" ]]; then
            local write_flags="append"
            [[ "$tmpl_flags" == *"once"* ]] && write_flags="once"
            [[ "$tmpl_flags" == *"override"* ]] && write_flags="override"
            _write_file "$tmpl_target" "$content" "$write_flags"

            local post_hook=""
            if [[ "$tmpl_flags" =~ post=\"([^\"]+)\" ]]; then
                post_hook="${BASH_REMATCH[1]}"
            elif [[ "$tmpl_flags" =~ post=([^:]+) ]]; then
                post_hook="${BASH_REMATCH[1]}"
            fi
            if [[ -n "$post_hook" ]]; then
                if [[ "$DRY_RUN" == true ]]; then
                    log_action "Would run template post hook: $post_hook"
                else
                    _run_script "$post_hook" "Running template hook: $tmpl_target" || log_warn "Template hook failed for '$tmpl_target'."
                fi
            fi
        fi
    done
}

deploy_templates() {
    local pdir="${1:-$PACKAGES_DIR}"
    [[ ! -d "$pdir" ]] && return 0
    _preload_all_manifests "$pdir"

    local group pkg
    while IFS= read -r group; do
        [[ -z "$group" ]] && continue
        _group_selected "$group" || continue

        while IFS= read -r pkg; do
            [[ -z "$pkg" ]] && continue
            local conf_file="$pdir/$group/$pkg.conf"
            [[ ! -f "$conf_file" ]] && continue

            if _package_is_active "$conf_file"; then
                deploy_package_templates "$conf_file"
            fi
        done < <(_get_group_packages "$group")
    done < <(_get_groups)
}

_ensure_stow_ignore() {
    [[ "$DRY_RUN" == true ]] && return
    local ignore_file="$DOTFILES_DIR/.stow-local-ignore"
    if [[ ! -f "$ignore_file" ]]; then
        mkdir -p "$DOTFILES_DIR"
        cat << 'EOF' > "$ignore_file"
^packages\.conf$
^myconfig.*$
^config$
^setup\.sh$
^script\.sh$
^README.*$
^LICENSE.*$
^\.git.*$
EOF
    fi
}

# ---------------------------------------------------------------------------
# Stow deployment: symlink dotfile configs from $DOTFILES_DIR into $HOME
# ---------------------------------------------------------------------------
deploy_stow() {
    mkdir -p "$DOTFILES_DIR"
    _ensure_stow_ignore

    # Clean up and back up any pre-existing unlinked regular files in $HOME before stowing
    local file dest rel real_dest real_stow
    while IFS= read -r -d '' file; do
        rel="${file#"$DOTFILES_DIR/"}"
        [[ "$rel" == ".git"* || "$rel" == ".stow-local-ignore" ]] && continue
        dest="$HOME/$rel"
        if [[ -e "$dest" || -L "$dest" ]]; then
            real_dest="$(readlink -f "$dest" 2>/dev/null || true)"
            real_stow="$(readlink -f "$file" 2>/dev/null || true)"
            if [[ -n "$real_stow" && "$real_dest" != "$real_stow" ]]; then
                if [[ -f "$dest" && ! -L "$dest" ]]; then
                    if [[ "$DRY_RUN" == true ]]; then
                        log_action "Would back up existing file before stow: ${rel}"
                    else
                        _get_backup_dir
                        mkdir -p "$BACKUP_DIR/$(dirname "$rel")"
                        local file_sha="" file_mode=""
                        if command -v sha256sum >/dev/null 2>&1; then
                            read -r file_sha _ < <(sha256sum "$dest" 2>/dev/null || true)
                        fi
                        if command -v stat >/dev/null 2>&1; then
                            file_mode="$(stat -c '%a' "$dest" 2>/dev/null || echo "644")"
                        fi
                        mv "$dest" "$BACKUP_DIR/$rel"
                        BACKUP_COUNT=$((BACKUP_COUNT + 1))
                        local manifest_file="$BACKUP_DIR/.backup_manifest.json"
                        local entry_json
                        entry_json="{\"rel\":\"${rel}\",\"dest\":\"${dest}\",\"sha256\":\"${file_sha}\",\"mode\":\"${file_mode}\",\"timestamp\":\"$(date -u +%Y-%m-%dT%H:%M:%SZ)\"}"
                        if [[ ! -f "$manifest_file" ]]; then
                            printf '[\n  %s\n]\n' "$entry_json" > "$manifest_file"
                        else
                            sed -i '$d' "$manifest_file" 2>/dev/null || true
                            printf ',\n  %s\n]\n' "$entry_json" >> "$manifest_file"
                        fi
                        log_action "Backed up existing file before stow: ${rel}"
                    fi
                elif [[ -L "$dest" ]]; then
                    if [[ "$DRY_RUN" == true ]]; then
                        log_action "Would remove obsolete symlink before stow: ${rel}"
                    else
                        rm -f "$dest"
                    fi
                fi
            fi
        fi
    done < <(find "$DOTFILES_DIR" -type f -print0)

    if command -v stow >/dev/null 2>&1; then
        if [[ "$DRY_RUN" == true ]]; then
            log_action "Would link dotfiles with GNU Stow"
        else
            stow -R --target="$HOME" --dir="$DOTFILES_DIR" .
            log_success "Linked dotfiles with GNU Stow."
        fi
    else
        local file dest ignore_patterns=()
        if [[ -f "$DOTFILES_DIR/.stow-local-ignore" ]]; then
            local p
            while IFS= read -r p || [[ -n "$p" ]]; do
                p="${p#"${p%%[![:space:]]*}"}"; p="${p%"${p##*[![:space:]]}"}"
                [[ -z "$p" || "$p" == '#'* ]] && continue
                ignore_patterns+=("$p")
            done < "$DOTFILES_DIR/.stow-local-ignore"
        fi

        while IFS= read -r -d '' file; do
            local rel="${file#"$DOTFILES_DIR/"}"
            [[ "$rel" == ".git"* || "$rel" == ".stow-local-ignore" ]] && continue
            local skip=false pat
            for pat in "${ignore_patterns[@]}"; do
                if [[ "$rel" =~ $pat ]]; then
                    skip=true
                    break
                fi
            done
            [[ "$skip" == true ]] && continue

            dest="$HOME/$rel"
            if [[ "$DRY_RUN" == true ]]; then
                log_action "Would link $file to $dest"
            else
                mkdir -p "$(dirname "$dest")"
                ln -sf "$file" "$dest"
            fi
        done < <(find "$DOTFILES_DIR" -type f -print0)
        log_success "Linked dotfiles directly."
    fi
}

# =============================================================================
#  SYSTEM & TOOL INTEGRATIONS (Git, SSH, WSL)
# =============================================================================

configure_git() {
    local name="${1:-${GIT_USER_NAME:-}}"
    local email="${2:-}"

    _git_set() {
        local key="$1" val="$2"
        if [[ "$DRY_RUN" == true ]]; then
            log_action "Would set git ${key}: ${val}"
        else
            git config --global "$key" "$val" || log_warn "Failed to set git config '${key}'."
        fi
    }

    if [[ -n "$name" ]]; then
        local cur_name
        cur_name="$(git config --global user.name 2>/dev/null || true)"
        if [[ "$name" != "$cur_name" ]]; then
            _git_set user.name "$name"
            if [[ "$DRY_RUN" != true ]]; then log_success "Set git user.name: ${name}"; fi
        else
            log_info "Git user.name already set: ${name}"
        fi
    fi

    [[ -n "${GIT_DEFAULT_BRANCH:-}" ]] && _git_set init.defaultBranch "$GIT_DEFAULT_BRANCH"
    [[ -n "${GIT_EDITOR:-}" ]] && _git_set core.editor "$GIT_EDITOR"

    if [[ -n "${GIT_SIGNING_KEY:-}" ]]; then
        _git_set user.signingKey "$GIT_SIGNING_KEY"
        _git_set commit.gpgSign true
        if [[ "$DRY_RUN" != true ]]; then log_info "Git commit signing enabled: ${GIT_SIGNING_KEY}"; fi
    fi

    if [[ -n "$email" ]]; then
        local cur_email
        cur_email="$(git config --global user.email 2>/dev/null || true)"
        if [[ "$email" != "$cur_email" ]]; then
            _git_set user.email "$email"
            if [[ "$DRY_RUN" != true ]]; then log_success "Set git user.email: ${email}"; fi
        else
            log_info "Git user.email already set: ${email}"
        fi
    fi
}

setup_github_ssh() {
    local email="${1:-}"

    local ssh_dir="$HOME/.ssh"
    local key_path="$ssh_dir/id_ed25519"
    local pub_key_path="${key_path}.pub"
    local key_to_use=""

    if [[ "$DRY_RUN" == true ]]; then
        log_action "Would check existing SSH keys in ${ssh_dir}"
        log_action "Would generate Ed25519 SSH key for '${email:-user@example.com}'"
        log_action "Would add github.com host key to ${ssh_dir}/known_hosts"
        log_action "Would upload public SSH key to GitHub via gh CLI"
        return 0
    fi

    mkdir -p -m 700 "$ssh_dir"

    local existing_key=""
    local k
    for k in "$ssh_dir/id_ed25519" "$ssh_dir/id_rsa" "$ssh_dir/id_ecdsa"; do
        if [[ -f "$k" && -f "${k}.pub" ]]; then
            existing_key="$k"
            break
        fi
    done

    if [[ -n "$existing_key" ]]; then
        log_info "Found existing SSH key: ${existing_key}"
        if _prompt_confirm "Use existing SSH key (${existing_key}) for GitHub?" true; then
            key_to_use="$existing_key"
        fi
    fi

    if [[ -z "$key_to_use" ]]; then
        if [[ -z "$email" ]]; then
            log_warn "Git email is not configured. Cannot generate SSH key."
            return 0
        fi

        if [[ -f "$key_path" ]]; then
            log_warn "SSH key '${key_path}' already exists. Skipping key generation."
            key_to_use="$key_path"
        elif _prompt_confirm "Generate new Ed25519 SSH key for GitHub (${email})?" true; then
            ssh-keygen -t ed25519 -C "$email" -f "$key_path" -N "" || {
                log_error "Failed to generate SSH key."
                return 1
            }
            chmod 600 "$key_path"
            chmod 644 "$pub_key_path"
            log_success "Generated SSH key: ${key_path}"
            key_to_use="$key_path"
        else
            log_info "Skipped SSH key generation."
            return 0
        fi
    fi

    if [[ -n "$key_to_use" && -f "$key_to_use" ]]; then
        if command -v ssh-add >/dev/null 2>&1; then
            if [[ -z "${SSH_AUTH_SOCK:-}" ]]; then
                eval "$(ssh-agent -s)" >/dev/null 2>&1 || true
            fi
            ssh-add "$key_to_use" >/dev/null 2>&1 || true
        fi
    fi

    if command -v ssh-keyscan >/dev/null 2>&1 && ! ssh-keygen -F github.com -f "$ssh_dir/known_hosts" >/dev/null 2>&1; then
        log_info "Adding github.com to ${ssh_dir}/known_hosts"
        touch "$ssh_dir/known_hosts" && chmod 600 "$ssh_dir/known_hosts"
        ssh-keyscan -t ed25519,rsa github.com 2>/dev/null >> "$ssh_dir/known_hosts" || true
    fi

    if [[ -n "$key_to_use" && -f "${key_to_use}.pub" ]]; then
        local pub_key="${key_to_use}.pub"
        if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
            if _prompt_confirm "Upload public SSH key to your GitHub account using gh CLI?" true; then
                local title
                title="$(hostname -s 2>/dev/null || echo "dotfiles-key")"
                if gh ssh-key add "$pub_key" --title "$title"; then
                    log_success "SSH public key uploaded to GitHub."
                else
                    log_warn "Could not upload SSH key via gh CLI (key may already exist on GitHub)."
                fi
            fi
        else
            log_info "GitHub CLI (gh) not authenticated. Add key manually:"
            printf '\n  ┌─ %s ──────────────────────────────────────────\n' "${BOLD}Public SSH Key${RESET}"
            printf '  │  %s%s%s\n' "${CLR_ACCENT}" "$(cat "$pub_key")" "${RESET}"
            printf '  └────────────────────────────────────────────────────────\n'
            printf '  Add key to GitHub: %shttps://github.com/settings/ssh/new%s\n\n' "${CLR_PRIMARY}${UNDERLINE:-}" "${RESET}"
        fi
    fi
}

deploy_wsl_conf() {
    [[ ! -f "$SCRIPT_DIR/wsl.conf" ]] && return
    if [[ "$DRY_RUN" == true ]]; then
        log_action "Would deploy wsl.conf -> /etc/wsl.conf"; return
    fi
    if [[ -f /etc/wsl.conf && ! -L /etc/wsl.conf ]]; then
        _get_backup_dir
        mkdir -p "$BACKUP_DIR/etc"
        _sudo cp /etc/wsl.conf "$BACKUP_DIR/etc/wsl.conf"
    fi
    _sudo cp "$SCRIPT_DIR/wsl.conf" /etc/wsl.conf
    _sudo chown root:root /etc/wsl.conf 2>/dev/null || true
    _sudo chmod 644 /etc/wsl.conf
    log_success "Configured /etc/wsl.conf."
}

# ── Module: src/tools.sh ──
# =============================================================================
#  DEVELOPER & QA TOOLS (Fmt, Lint, Doctor, Symlinks)
# =============================================================================

_format_manifest() {
    local mode="format"
    local targets=()
    local arg
    for arg in "$@"; do
        if [[ "$arg" == "--check-only" ]]; then
            mode="--check-only"
        elif [[ -n "$arg" ]]; then
            targets+=("$arg")
        fi
    done

    if [[ ${#targets[@]} -eq 0 ]]; then
        targets=("$SCRIPT_DIR/packages/"*/*.conf "$GROUPS_CONF" "$SCRIPT_DIR/"*.conf)
    fi
    local unformatted=0

    # Format packages/*/*.conf, _groups.conf and root *.conf files
    local cfg
    for cfg in "${targets[@]}"; do
        [[ -f "$cfg" ]] || continue
        local tmp_cfg
        tmp_cfg="$(mktemp "${cfg}.XXXXXX")"
        _TRACKED_TMP_FILES+=("$tmp_cfg")
        sed 's/[[:space:]]*$//' "$cfg" > "$tmp_cfg"
        [[ -n "$(tail -c 1 "$tmp_cfg" 2>/dev/null)" ]] && echo "" >> "$tmp_cfg"

        if ! cmp -s "$cfg" "$tmp_cfg"; then
            if [[ "$mode" == "--check-only" ]]; then
                unformatted=$((unformatted + 1))
            else
                chmod 644 "$tmp_cfg" 2>/dev/null || true
                mv "$tmp_cfg" "$cfg"
                log_success "Formatted $(basename "$cfg")"
            fi
        fi
        rm -f "$tmp_cfg"
    done

    if [[ "$mode" == "--check-only" ]]; then
        [[ "$unformatted" -gt 0 ]] && return 1 || return 0
    else
        log_success "Formatting complete."
        exit 0
    fi
}


_lint_manifest() {
    [[ ! -d "$PACKAGES_DIR" ]] && { log_error "Packages directory not found."; exit 1; }
    _ui_header "Running Static Lint Checks"
    local errors=0

    _preload_all_manifests "$PACKAGES_DIR"

    local valid_groups=() gdir conf_file
    for gdir in "$PACKAGES_DIR"/*; do
        [[ ! -d "$gdir" ]] && continue
        valid_groups+=("$(basename "$gdir")")
    done

    for gdir in "$PACKAGES_DIR"/*; do
        [[ ! -d "$gdir" ]] && continue
        for conf_file in "$gdir"/*.conf; do
            [[ ! -f "$conf_file" ]] && continue
            local rel_file="${conf_file#"$SCRIPT_DIR/"}"
            
            local in_tmpl=false
            while IFS= read -r raw_line || [[ -n "$raw_line" ]]; do
                line="${raw_line#"${raw_line%%[![:space:]]*}"}"
                line="${line%"${line##*[![:space:]]}"}"
                if [[ "$line" =~ ^\[(.*)\]$ ]]; then
                    local header="${BASH_REMATCH[1]}"
                    local sec_type="" sec_ident="" sec_mod="" is_valid=0
                    _parse_section_header "$header" sec_type sec_ident sec_mod is_valid
                    if [[ "$is_valid" -eq 0 ]]; then
                        if [[ "$sec_type" == "template" ]]; then
                            in_tmpl=true
                        else
                            in_tmpl=false
                        fi
                    elif [[ "$in_tmpl" == false ]]; then
                        log_error "$rel_file: Invalid section header or modifier syntax: '[$header]'"
                        errors=$((errors + 1))
                    fi
                fi
            done < "$conf_file"

            local bashrc_content="${_CONF_BASHRC["$conf_file"]:-}"
            if [[ -n "$bashrc_content" ]]; then
                if ! bash -n <<< "$bashrc_content" 2>/dev/null; then
                    log_error "$rel_file: [bashrc] block contains syntax errors."
                    errors=$((errors + 1))
                fi
            fi

            local p_scope="${_CONF_PKG_SCOPE["$conf_file"]:-system}"
            case "$p_scope" in
                system|user|script) ;;
                *)
                    log_error "$rel_file: Invalid scope '$p_scope'. Allowed scopes: system, user, script."
                    errors=$((errors + 1))
                    ;;
            esac
        done
    done

    local cfg
    for cfg in "$SCRIPT_DIR/"*.conf; do
        [[ ! -f "$cfg" ]] && continue
        local fname
        fname="$(basename "$cfg")"

        local raw_line line
        while IFS= read -r raw_line || [[ -n "$raw_line" ]]; do
            line="${raw_line#"${raw_line%%[![:space:]]*}"}"
            line="${line%"${line##*[![:space:]]}"}"
            if [[ "$line" =~ ^\[(.*)\]$ ]]; then
                local header="${BASH_REMATCH[1]}"
                local sec_type="" sec_ident="" sec_mod="" is_valid=0
                _parse_section_header "$header" sec_type sec_ident sec_mod is_valid
                if [[ "$is_valid" -ne 0 ]]; then
                    log_error "Config $fname: Invalid section header or modifier syntax: '[$header]'"
                    errors=$((errors + 1))
                fi
            fi
        done < "$cfg"
    done

    if [[ -n "${_CONF_PKG_KEYS["global:INSTALL_GROUPS"]:-}" ]]; then
        local raw_ig="${_CONF_PKG_KEYS["global:INSTALL_GROUPS"]}"
        raw_ig="${raw_ig//[()]/}"
        raw_ig="${raw_ig//,/ }"
        local g
        for g in $raw_ig; do
            [[ -z "$g" ]] && continue
            local found=false vg
            for vg in "${valid_groups[@]}"; do
                if [[ "$g" == "$vg" ]]; then
                    found=true
                    break
                fi
            done
            if [[ "$found" == false ]]; then
                log_error "Configuration references unknown package group: '$g'"
                errors=$((errors + 1))
            fi
        done
    fi

    if ! _format_manifest "$GROUPS_CONF" --check-only; then
        log_warn "Configuration files need formatting. Run './setup.sh --format' to fix."
        errors=$((errors + 1))
    fi

    if [[ "$errors" -eq 0 ]]; then
        log_success "Lint passed with 0 errors."
        exit 0
    else
        log_error "Lint found ${errors} error(s)."
        exit 1
    fi
}


_doctor_check() {
    _ui_header "System Diagnostics"
    local warnings=0 errors=0

    # 1. Shell & Prerequisites
    printf "\n  %s[1/6]%s %s\n" "${CLR_MUTED}" "${RESET}" "${BOLD}Shell and Core Tools${RESET}"
    if [[ "${BASH_VERSINFO[0]}" -ge 4 ]]; then
        log_success "Bash version: ${BASH_VERSION}"
    else
        log_error "Bash version ${BASH_VERSION} is not supported. Bash 4.0 or newer is required."
        errors=$((errors + 1))
    fi

    local tool
    for tool in git curl stow awk tar gzip; do
        if command -v "$tool" >/dev/null 2>&1; then
            log_success "Available: $tool (${CLR_MUTED}$(command -v "$tool")${RESET})"
        else
            log_warn "Missing: $tool"
            warnings=$((warnings + 1))
        fi
    done

    # 2. Package Managers & Lock State
    printf "\n  %s[2/6]%s %s\n" "${CLR_MUTED}" "${RESET}" "${BOLD}Package Managers & Lock State${RESET}"
    local pm_found=0 pm
    for pm in apt dnf pacman apk brew mise; do
        if command -v "$pm" >/dev/null 2>&1; then
            log_success "Package manager found: ${BOLD}$pm${RESET}"
            pm_found=$((pm_found + 1))
        fi
    done
    [[ $pm_found -eq 0 ]] && { log_warn "No supported package manager found (apt/dnf/pacman/apk/brew/mise)."; warnings=$((warnings + 1)); }

    # 3. Network & GitHub API Reachability
    printf "\n  %s[3/6]%s %s\n" "${CLR_MUTED}" "${RESET}" "${BOLD}Network & Rate-Limit Diagnostics${RESET}"
    if _check_network; then
        log_success "Internet connectivity: reachable"
    else
        log_warn "Internet connectivity: unreachable or restricted"
        warnings=$((warnings + 1))
    fi

    if command -v curl >/dev/null 2>&1; then
        local token="${GITHUB_TOKEN:-${GH_TOKEN:-}}"
        local -a gh_auth=()
        [[ -n "$token" ]] && gh_auth=(-H "Authorization: Bearer $token")
        local gh_hdrs
        gh_hdrs="$(curl --proto '=https' --tlsv1.2 -sSI --connect-timeout 3 --max-time 5 "${gh_auth[@]}" https://api.github.com/rate_limit 2>/dev/null || true)"
        if [[ -n "$gh_hdrs" ]]; then
            local rem_limit=""
            if [[ "$gh_hdrs" =~ x-ratelimit-remaining:[[:space:]]*([0-9]+) ]]; then
                rem_limit="${BASH_REMATCH[1]}"
            fi
            if [[ -n "$rem_limit" ]]; then
                if [[ "$rem_limit" -gt 0 ]]; then
                    log_success "GitHub API reachable (Rate limit remaining: ${rem_limit})"
                else
                    log_warn "GitHub API rate limit exhausted (0 remaining). Set GITHUB_TOKEN to resolve."
                    warnings=$((warnings + 1))
                fi
            else
                log_success "GitHub API reachable"
            fi
        else
            log_warn "GitHub API unreachable or timed out."
            warnings=$((warnings + 1))
        fi
    fi

    # 4. Environment & Directories
    printf "\n  %s[4/6]%s %s\n" "${CLR_MUTED}" "${RESET}" "${BOLD}Environment and Directories${RESET}"
    if [[ ":$PATH:" == *":$HOME/.local/bin:"* ]]; then
        log_success "PATH contains $HOME/.local/bin"
    else
        log_warn "PATH does not include $HOME/.local/bin"
        warnings=$((warnings + 1))
    fi

    local d
    for d in "$HOME/.local/bin" "${XDG_CONFIG_HOME:-$HOME/.config}" "${XDG_DATA_HOME:-$HOME/.local/share}" "${XDG_CACHE_HOME:-$HOME/.cache}" "${XDG_STATE_HOME:-$HOME/.local/state}"; do
        if [[ -d "$d" ]]; then
            log_success "Directory exists: ${d}"
        else
            if [[ "${1:-}" == "--fix" || "${2:-}" == "--fix" ]]; then
                mkdir -p "$d"
                log_success "Created missing directory: ${d}"
            else
                log_warn "Directory missing: ${d}"
                warnings=$((warnings + 1))
            fi
        fi
    done

    # 5. Broken Symlink Check
    printf "\n  %s[5/6]%s %s\n" "${CLR_MUTED}" "${RESET}" "${BOLD}Symlink Integrity${RESET}"
    local broken_links=()
    while IFS= read -r -d '' link; do
        if [[ ! -e "$link" ]]; then
            broken_links+=("$link")
        fi
    done < <(find "$HOME" "$HOME/.config" -maxdepth 1 -type l -print0 2>/dev/null)

    if [[ ${#broken_links[@]} -eq 0 ]]; then
        log_success "No broken symlinks found."
    else
        if [[ "${1:-}" == "--fix" || "${2:-}" == "--fix" ]]; then
            for link in "${broken_links[@]}"; do
                rm -f "$link"
                log_success "Removed broken symlink: $link"
            done
        else
            log_warn "Found ${#broken_links[@]} broken symlink(s):"
            for link in "${broken_links[@]}"; do
                printf "    %s %s\n" "${CLR_MUTED}•${RESET}" "$link"
            done
            log_info "Run './setup.sh --doctor --fix' or './setup.sh --clean-symlinks' to remove them."
            warnings=$((warnings + 1))
        fi
    fi

    # 6. Manifest Inventory Audit
    printf "\n  %s[6/6]%s %s\n" "${CLR_MUTED}" "${RESET}" "${BOLD}Package Inventory Audit${RESET}"
    if [[ -d "$PACKAGES_DIR" ]]; then
        local total_pkgs=0 installed_pkgs=0 sys_total=0 sys_inst=0 usr_total=0 usr_inst=0
        local gdir conf_file pkg bin scope
        for gdir in "$PACKAGES_DIR"/*; do
            [[ ! -d "$gdir" ]] && continue
            for conf_file in "$gdir"/*.conf; do
                [[ ! -f "$conf_file" ]] && continue
                total_pkgs=$((total_pkgs + 1))
                pkg="$(basename "$conf_file" .conf)"
                _parse_manifest_file "$conf_file" "$pkg"
                bin="${pkg_bin:-$pkg}"
                scope="$pkg_scope"
                if [[ "$scope" == "user" ]]; then
                    usr_total=$((usr_total + 1))
                    if _check_bins_scoped "$bin" "user"; then
                        usr_inst=$((usr_inst + 1))
                        installed_pkgs=$((installed_pkgs + 1))
                    fi
                elif [[ "$scope" == "system" ]]; then
                    sys_total=$((sys_total + 1))
                    if _check_bins_scoped "$bin" "system"; then
                        sys_inst=$((sys_inst + 1))
                        installed_pkgs=$((installed_pkgs + 1))
                    fi
                else
                    if _check_bins "$bin"; then
                        installed_pkgs=$((installed_pkgs + 1))
                    fi
                fi
            done
        done
        log_info "Package inventory: ${installed_pkgs}/${total_pkgs} installed (system: ${sys_inst}/${sys_total}, user: ${usr_inst}/${usr_total})."
    else
        log_warn "Packages directory not found. Skipping inventory audit."
        warnings=$((warnings + 1))
    fi

    _ui_header "Diagnostic Results"
    if [[ $errors -eq 0 ]]; then
        log_success "Diagnostics passed: ${warnings} warning(s), 0 error(s)."
        exit 0
    else
        log_error "Diagnostics failed: ${errors} error(s), ${warnings} warning(s)."
        exit 1
    fi
}

_clean_broken_symlinks() {
    log_info "Scanning for broken symlinks..."
    local link count=0
    while IFS= read -r -d '' link; do
        if [[ ! -e "$link" ]]; then
            log_info "Removing broken symlink: ${link}"
            rm -f "$link"
            count=$((count + 1))
        fi
    done < <(find "$HOME" "$HOME/.config" -maxdepth 1 -type l -print0 2>/dev/null)
    log_success "Removed ${count} broken symlink(s)."
    exit 0
}

_export_diagnostics() {
    local outfile="${1:-dotfiles-diagnostics.json}"
    local distro arch pm conds
    distro="$(_get_distro_name)"
    arch="$(_get_arch)"
    pm="$(_detect_pm)"
    conds="$(_get_detected_conds)"

    cat << EOF > "$outfile"
{
  "timestamp": "$(date -u +"%Y-%m-%dT%H:%M:%SZ" 2>/dev/null || date)",
  "distro": "${distro}",
  "arch": "${arch}",
  "package_manager": "${pm}",
  "conditions": "${conds}",
  "profile": "$(_get_profile)",
  "bash_version": "${BASH_VERSION}",
  "failed_packages": [
$(local i=0; for fp in "${_FAILED_PACKAGES[@]}"; do [[ $i -gt 0 ]] && printf ',\n'; printf '    {"package": "%s", "reason": "%s"}' "$fp" "${_FAILURE_REASONS["$fp"]:-unknown}"; i=$((i+1)); done)
  ]
}
EOF
    log_success "Exported diagnostics to ${outfile}"
    exit 0
}

# ── Module: src/main.sh ──
# =============================================================================
#  CLI & MAIN ORCHESTRATOR
# =============================================================================

# ---------------------------------------------------------------------------
# Help & Manifest Querying
# ---------------------------------------------------------------------------
_show_help() {
    printf '%s\n' "${CLR_PRIMARY}${BOLD}Dotfiles Setup${RESET}"
    printf '\n%s\n' "${BOLD}USAGE${RESET}"
    printf '    ./setup.sh %s[OPTIONS]%s\n' "${CLR_ACCENT}" "${RESET}"
    printf '\n%s\n' "${BOLD}OPTIONS${RESET}"
    printf '    %s %-30s %s\n' \
        "${CLR_PRIMARY}•${RESET}" '-c, --config <file>'        'Load configuration file' \
        "${CLR_PRIMARY}•${RESET}" '-v, --verbose'               'Show verbose command output' \
        "${CLR_PRIMARY}•${RESET}" '-f, --force, --reset'        'Overwrite existing files and bypass locks' \
        "${CLR_PRIMARY}•${RESET}" '    --verify-scripts'        'Prompt before running installation scripts' \
        "${CLR_PRIMARY}•${RESET}" '    --list'                  'List available packages by group' \
        "${CLR_PRIMARY}•${RESET}" '    --fmt, --format'         'Format configuration and manifest files' \
        "${CLR_PRIMARY}•${RESET}" '    --lint'                  'Validate manifest and configuration syntax' \
        "${CLR_PRIMARY}•${RESET}" '    --clean-symlinks'        'Remove broken dotfile symlinks in home directory' \
        "${CLR_PRIMARY}•${RESET}" '    --rollback [snapshot]'   'Roll back snapshot from ~/.dotfiles.bak' \
        "${CLR_PRIMARY}•${RESET}" '    --export-diagnostics'    'Export diagnostic snapshot to JSON file' \
        "${CLR_PRIMARY}•${RESET}" '    --doctor [--fix]'        'Check system environment and repair missing paths' \
        "${CLR_PRIMARY}•${RESET}" '-h, --help'                  'Show help'
    printf '\n%s\n' "${BOLD}EXAMPLES${RESET}"
    printf '    %s %s\n' \
        "${CLR_MUTED}\$${RESET}" './setup.sh' \
        "${CLR_MUTED}\$${RESET}" './setup.sh --config work.conf' \
        "${CLR_MUTED}\$${RESET}" './setup.sh --rollback' \
        "${CLR_MUTED}\$${RESET}" './setup.sh --doctor --fix' \
        "${CLR_MUTED}\$${RESET}" './setup.sh --export-diagnostics' \
        "${CLR_MUTED}\$${RESET}" './setup.sh --fmt' \
        "${CLR_MUTED}\$${RESET}" './setup.sh --lint' \
        "${CLR_MUTED}\$${RESET}" './setup.sh --clean-symlinks'
    printf '\n%s\n' "${BOLD}FILES${RESET}"
    printf '    %-24s %s\n' \
        'packages/'               'Package definitions and configuration templates' \
        'packages/_groups.conf'   'Package group definitions' \
        'default.conf'            'Base settings and shell templates' \
        'example.conf'            'Example custom configuration file'
    exit 0
}

_list_all() {
    [[ ! -d "$PACKAGES_DIR" ]] && { log_error "Packages directory not found."; exit 1; }
    printf '\n%s %s\n\n' "${CLR_PRIMARY}${SYM_DOT}${RESET}" "${BOLD}Available Packages by Group${RESET}"
    local gname pkg
    while IFS= read -r gname; do
        [[ -z "$gname" ]] && continue
        local gdesc="$(_get_group_meta "$gname" "description")"
        if [[ -n "$gdesc" ]]; then
            printf '  %s %s\n' "${CLR_ACCENT}${BOLD}[${gname}]${RESET}" "${CLR_MUTED}- ${gdesc}${RESET}"
        else
            printf '  %s\n' "${CLR_ACCENT}${BOLD}[${gname}]${RESET}"
        fi
        while IFS= read -r pkg; do
            [[ -n "$pkg" ]] && printf '    %s %s\n' "${CLR_MUTED}•${RESET}" "$pkg"
        done < <(_get_group_packages "$gname")
    done < <(_get_groups)
    exit 0
}

# ---------------------------------------------------------------------------
# CLI argument parser
# ---------------------------------------------------------------------------
_parse_args() {
    while [[ $# -gt 0 ]]; do
        case "$1" in
            -c|--config)                          CONFIG_FILE="$2"; shift 2 ;;
            --config=*)                           CONFIG_FILE="${1#*=}"; shift ;;
            --skip-upgrade)                       SKIP_UPGRADE=true; shift ;;
            -v|--verbose)                         VERBOSE=true; shift ;;
            -f|--force|--reset)                   FORCE=true; shift ;;
            --verify-scripts)                     VERIFY_SCRIPTS=true; shift ;;
            --profile=*)                          PROFILE="${1#*=}"; CLI_EXPLICIT_GROUPS=true; shift ;;
            --profile)                            PROFILE="$2"; CLI_EXPLICIT_GROUPS=true; shift 2 ;;
            --offline)                            OFFLINE=true; shift ;;
            -y|--non-interactive)                 NON_INTERACTIVE=true; shift ;;
            --list|--list-groups|--list-packages) _list_all ;;
            --lint)                               _lint_manifest ;;
            --fmt|--format)                       _format_manifest ;;
            --clean-symlinks)                     _clean_broken_symlinks ;;
            --rollback=*)                         _rollback_latest_backup "${1#*=}"; exit $? ;;
            --rollback)                           
                if [[ -n "${2:-}" && "${2:-}" != -* ]]; then
                    _rollback_latest_backup "$2"; exit $?
                else
                    _rollback_latest_backup ""; exit $?
                fi
                ;;
            --export-diagnostics)                 _export_diagnostics "${2:-dotfiles-diagnostics.json}"; exit $? ;;
            --export-diagnostics=*)               _export_diagnostics "${1#*=}"; exit $? ;;
            --doctor|--check)                     
                if [[ "${2:-}" == "--fix" || "${2:-}" == "-f" ]]; then
                    _doctor_check "--fix"
                else
                    _doctor_check
                fi
                ;;
            -h|--help) _show_help ;;
            --) shift; break ;;
            -*) log_error "Unknown option '$1'. Run './setup.sh --help' for usage."; exit 1 ;;
            *)  break ;;
        esac
    done
}

# =============================================================================
#  MAIN ENTRYPOINT
# =============================================================================

_main() {
    local start_time=$SECONDS
    _parse_args "$@"

    local distro; distro="$(_get_distro_name)"
    local arch; arch="$(_get_arch)"
    local pm; pm="$(_detect_pm)"
    local conds; conds="$(_get_detected_conds)"

    if [[ -t 2 && -z "${NO_COLOR:-}" ]]; then
        printf '\n%s %s\n' "${CLR_PRIMARY}${BOLD}Dotfiles Setup${RESET}" "${CLR_MUTED}v2.0${RESET}" >&2
    else
        printf '\nDotfiles Setup v2.0\n' >&2
    fi

    # ── Phase 1: Preflight & Environment ──
    _ui_phase 1 6 "Preflight & System Environment"
    _check_disk_space 500 "$HOME" || exit 1

    local net_status="online"
    if ! _check_network; then
        net_status="offline/limited"
    fi
    printf '  %s (%s) · %s · %s · %s\n' "$distro" "$arch" "$pm" "$conds" "$net_status"
    [[ "$net_status" == "offline/limited" ]] && log_warn "Network appears offline or limited. Online downloads may fail."

    # ── Phase 2: Configuration Profile & Manifests ──
    _ui_phase 2 6 "Configuration Profile & Manifests"
    _preload_all_manifests "$PACKAGES_DIR"

    local cfg_name="default.conf"
    [[ -n "${CONFIG_FILE:-}" ]] && cfg_name="$(basename "$CONFIG_FILE")"
    printf '  Loaded configuration: %s\n' "${BOLD}${cfg_name}${RESET}"

    # ── Phase 3: Identity & Privilege Acquisition ──
    _ui_phase 3 6 "Identity & Privilege Acquisition"
    _PM="$(_detect_pm)"
    _acquire_sudo "$_PM"

    GIT_USER_NAME="${_CONF_PKG_KEYS["core/git:GIT_USER_NAME"]:-${_CONF_PKG_KEYS["git:GIT_USER_NAME"]:-${_CONF_PKG_KEYS["global:GIT_USER_NAME"]:-${GIT_USER_NAME:-}}}}"
    GIT_EMAIL="${_CONF_PKG_KEYS["core/git:GIT_EMAIL"]:-${_CONF_PKG_KEYS["git:GIT_EMAIL"]:-${_CONF_PKG_KEYS["global:GIT_EMAIL"]:-${GIT_EMAIL:-}}}}"

    local FINAL_NAME=""
    local CUR_NAME
    CUR_NAME="$(git config --global user.name 2>/dev/null || true)"
    if [[ -n "${GIT_USER_NAME:-}" ]]; then
        FINAL_NAME="$GIT_USER_NAME"
        printf '  %-12s %s\n' "user.name" "$FINAL_NAME"
    elif [[ "$DRY_RUN" == false && "${NON_INTERACTIVE:-false}" == false && ( -t 0 || -t 1 || -c /dev/tty ) ]]; then
        FINAL_NAME="$(_ui_input "user.name" "$CUR_NAME")"
    elif [[ -n "$CUR_NAME" ]]; then
        FINAL_NAME="$CUR_NAME"
        printf '  %-12s %s\n' "user.name" "$FINAL_NAME"
    else
        printf '  %-12s %s\n' "user.name" "${CLR_MUTED}(skipped)${RESET}"
    fi

    local FINAL_EMAIL=""
    local CUR_EMAIL
    CUR_EMAIL="$(git config --global user.email 2>/dev/null || true)"

    if [[ -n "${GIT_EMAIL:-}" ]]; then
        _validate_email "$GIT_EMAIL" \
            || { log_error "Invalid GIT_EMAIL format in config: '$GIT_EMAIL'. Expected name@example.com."; exit 1; }
        FINAL_EMAIL="$GIT_EMAIL"
        printf '  %-12s %s\n' "user.email" "$FINAL_EMAIL"
    elif [[ "$DRY_RUN" == false && "${NON_INTERACTIVE:-false}" == false && ( -t 0 || -t 1 || -c /dev/tty ) ]]; then
        local git_input
        git_input="$(_ui_input "user.email" "$CUR_EMAIL")"
        if [[ -n "$git_input" ]]; then
            if _validate_email "$git_input"; then
                FINAL_EMAIL="$git_input"
            else
                log_warn "Invalid email address entered. Skipping email setup."
            fi
        fi
    elif [[ -n "$CUR_EMAIL" ]]; then
        FINAL_EMAIL="$CUR_EMAIL"
        printf '  %-12s %s\n' "user.email" "$FINAL_EMAIL"
    else
        printf '  %-12s %s\n' "user.email" "${CLR_MUTED}(skipped)${RESET}"
    fi

    # ── Phase 4: System Package Updates & Upgrades ──
    _ui_phase 4 6 "System Package Updates & Upgrades"
    _upgrade_system

    # ── Phase 5: Package Installation & Life-cycle Management ──
    _ui_phase 5 6 "Package Installation & Life-cycle Management"
    if [[ -d "$PACKAGES_DIR" ]]; then
        install_packages "$PACKAGES_DIR"
    else
        log_warn "Packages directory not found. Skipping package installation."
    fi

    # ── Phase 6: Template Deployment & Symlink Integration ──
    _ui_phase 6 6 "Template Deployment & Symlink Integration"

    local _prof_tmpl="${_CONF_TMPL_BUF[".profile"]:-${_CONF_TMPL_BUF["profile"]:-}}"
    local _bprof_tmpl="${_CONF_TMPL_BUF[".bash_profile"]:-${_CONF_TMPL_BUF["bash_profile"]:-}}"
    local _bashrc_tmpl="${_CONF_TMPL_BUF[".bashrc"]:-${_CONF_TMPL_BUF["bashrc"]:-}}"
    local _inputrc_tmpl="${_CONF_TMPL_BUF[".inputrc"]:-${_CONF_TMPL_BUF["inputrc"]:-}}"

    _prof_tmpl="${_prof_tmpl%__TMPL_SEP__}"
    _bprof_tmpl="${_bprof_tmpl%__TMPL_SEP__}"
    _bashrc_tmpl="${_bashrc_tmpl%__TMPL_SEP__}"
    _inputrc_tmpl="${_inputrc_tmpl%__TMPL_SEP__}"

    _write_file "~/.profile" "${TEMPLATE_OVERRIDE_PROFILE:-$_prof_tmpl}" "once"
    _write_file "~/.bash_profile" "${TEMPLATE_OVERRIDE_BASH_PROFILE:-$_bprof_tmpl}" "once"
    [[ -n "$_bashrc_tmpl" ]] && _write_file "~/.bashrc" "${TEMPLATE_OVERRIDE_BASHRC:-$_bashrc_tmpl}" "once"
    [[ -n "$_inputrc_tmpl" ]] && _write_file "~/.inputrc" "${TEMPLATE_OVERRIDE_INPUTRC:-$_inputrc_tmpl}" "once"

    # Deploy and integrate shell configuration
    if [[ -d "$PACKAGES_DIR" ]]; then
        local _bashrc_snippets
        _bashrc_snippets="$(_collect_bashrc_snippets "$PACKAGES_DIR")"
        if [[ -n "$_bashrc_snippets" && -f "$DOTFILES_DIR/.bashrc" ]]; then
            local target_rc="$DOTFILES_DIR/.bashrc"
            local b_start="# ── Tool integrations start ──"
            local b_end="# ── Tool integrations end ──"
            local new_block="${b_start}"$'\n'"${_bashrc_snippets}"$'\n'"${b_end}"
            local tmp_rc
            tmp_rc="$(mktemp "${target_rc}.XXXXXX")"
            _TRACKED_TMP_FILES+=("$tmp_rc")
            awk -v block="$new_block" '
                /# ── Tool integrations start ──/ || /# ── Tool integrations/ {
                    if (!replaced) {
                        print block
                        replaced = 1
                    }
                    in_block = 1
                    next
                }
                /# ── Tool integrations end ──/ {
                    in_block = 0
                    next
                }
                !in_block { print }
                END {
                    if (!replaced) {
                        print ""
                        print block
                    }
                }
            ' "$target_rc" > "$tmp_rc"
            chmod 644 "$tmp_rc" 2>/dev/null || true
            mv "$tmp_rc" "$target_rc"
        fi
    fi

    # Stow all generated dotfiles from dotfiles repository into $HOME.
    deploy_stow

    # Git personal settings: applied AFTER stow so global options write to stowed gitconfig.
    configure_git "${FINAL_NAME:-${GIT_USER_NAME:-}}" "${FINAL_EMAIL:-${GIT_EMAIL:-}}"

    setup_github_ssh "${FINAL_EMAIL:-${GIT_EMAIL:-}}"

    if _is_wsl && [[ -f "$SCRIPT_DIR/wsl.conf" ]]; then
        deploy_wsl_conf
    fi

    if [[ -n "${POST_INSTALL_HOOK:-}" ]]; then
        if [[ "$DRY_RUN" == true ]]; then
            log_action "Would run post-install hook: ${POST_INSTALL_HOOK}"
        else
            log_info "Running post-install hook: ${POST_INSTALL_HOOK}"
            _run_script "$POST_INSTALL_HOOK" || log_warn "Post-install hook failed."
        fi
    fi

    local total_elapsed=$(( SECONDS - start_time ))
    _ui_render_summary "$total_elapsed" "${#_CONF_PARSED[@]}" "${BACKUP_COUNT:-0}"
}

if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    _main "$@"
    exit $?
fi

return 0 2>/dev/null || exit 0

